-- QDITP.ACCOUNT_EXCEPTION_TICKET definition

CREATE TABLE "QDITP"."ACCOUNT_EXCEPTION_TICKET" 
   (	"ID" NUMBER NOT NULL ENABLE, 
	"TICKET_TYPE" VARCHAR2(64 CHAR) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"BIZ_KEY" VARCHAR2(128 CHAR) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"THIRD_USER_ID" VARCHAR2(128 CHAR) COLLATE "USING_NLS_COMP", 
	"TICKET_STATUS" VARCHAR2(32 CHAR) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"RETRY_COUNT" NUMBER, 
	"DETAIL" VARCHAR2(2000 CHAR) COLLATE "USING_NLS_COMP", 
	"CREATE_TMS" TIMESTAMP (6) NOT NULL ENABLE, 
	"CLOSE_TMS" TIMESTAMP (6), 
	"CLOSED_BY" VARCHAR2(64 CHAR) COLLATE "USING_NLS_COMP", 
	 CONSTRAINT "PK_ACCOUNT_EXCEPTION_TICKET" PRIMARY KEY ("ID")
  USING INDEX PCTFREE 10 INITRANS 2 MAXTRANS 255 COMPUTE STATISTICS 
  STORAGE(INITIAL 65536 NEXT 1048576 MINEXTENTS 1 MAXEXTENTS 2147483645
  PCTINCREASE 0 FREELISTS 1 FREELIST GROUPS 1
  BUFFER_POOL DEFAULT FLASH_CACHE DEFAULT CELL_FLASH_CACHE DEFAULT)
  TABLESPACE "USERS"  ENABLE, 
	 CONSTRAINT "UK_ACCT_EXC_TICKET_TYPE_KEY" UNIQUE ("TICKET_TYPE", "BIZ_KEY")
  USING INDEX PCTFREE 10 INITRANS 2 MAXTRANS 255 COMPUTE STATISTICS 
  STORAGE(INITIAL 65536 NEXT 1048576 MINEXTENTS 1 MAXEXTENTS 2147483645
  PCTINCREASE 0 FREELISTS 1 FREELIST GROUPS 1
  BUFFER_POOL DEFAULT FLASH_CACHE DEFAULT CELL_FLASH_CACHE DEFAULT)
  TABLESPACE "USERS"  ENABLE
   )  DEFAULT COLLATION "USING_NLS_COMP" SEGMENT CREATION IMMEDIATE 
  PCTFREE 10 PCTUSED 40 INITRANS 1 MAXTRANS 255 
 NOCOMPRESS LOGGING
  STORAGE(INITIAL 65536 NEXT 1048576 MINEXTENTS 1 MAXEXTENTS 2147483645
  PCTINCREASE 0 FREELISTS 1 FREELIST GROUPS 1
  BUFFER_POOL DEFAULT FLASH_CACHE DEFAULT CELL_FLASH_CACHE DEFAULT)
  TABLESPACE "USERS" ;

COMMENT ON COLUMN "QDITP"."ACCOUNT_EXCEPTION_TICKET"."ID" IS '主键，取 SEQ_ACCOUNT_EXCEPTION_TICKET';
   COMMENT ON COLUMN "QDITP"."ACCOUNT_EXCEPTION_TICKET"."TICKET_TYPE" IS '工单类型，如 SIGN_SYNC_RETRY_EXHAUSTED-签约展示账号同步重试超限';
   COMMENT ON COLUMN "QDITP"."ACCOUNT_EXCEPTION_TICKET"."BIZ_KEY" IS '业务幂等键，与 TICKET_TYPE 组成唯一索引；SIGN_SYNC_RETRY_EXHAUSTED 用 USER_PHONE_CHANGE_LOG.ID';
   COMMENT ON COLUMN "QDITP"."ACCOUNT_EXCEPTION_TICKET"."THIRD_USER_ID" IS '第三方用户标识，便于按用户排查，允许为空';
   COMMENT ON COLUMN "QDITP"."ACCOUNT_EXCEPTION_TICKET"."TICKET_STATUS" IS '工单状态，OPEN-待处理、CLOSED-已处理';
   COMMENT ON COLUMN "QDITP"."ACCOUNT_EXCEPTION_TICKET"."RETRY_COUNT" IS '开单时已重试次数';
   COMMENT ON COLUMN "QDITP"."ACCOUNT_EXCEPTION_TICKET"."DETAIL" IS '开单原因与现场信息快照，NEVER 写入密钥等敏感信息';
   COMMENT ON COLUMN "QDITP"."ACCOUNT_EXCEPTION_TICKET"."CREATE_TMS" IS '开单时间';
   COMMENT ON COLUMN "QDITP"."ACCOUNT_EXCEPTION_TICKET"."CLOSE_TMS" IS '关单时间';
   COMMENT ON COLUMN "QDITP"."ACCOUNT_EXCEPTION_TICKET"."CLOSED_BY" IS '关单人';
   COMMENT ON TABLE "QDITP"."ACCOUNT_EXCEPTION_TICKET"  IS '账户域异常工单表。补偿重试达上限等无法自愈的情况在此留一条待人工处理的记录。本表由 account-server 独占，其它域 NEVER 写入，各域应建自己的同类表';


-- QDITP.ACC_SIMULATION_HISTORY definition

CREATE TABLE "QDITP"."ACC_SIMULATION_HISTORY" 
   (	"ID" NUMBER(19,0) NOT NULL ENABLE, 
	"OPERATION" VARCHAR2(64 CHAR) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"TARGET_URL" VARCHAR2(512 CHAR) COLLATE "USING_NLS_COMP", 
	"TRANSPORT_SUCCESS" NUMBER(1,0) NOT NULL ENABLE, 
	"HTTP_STATUS" NUMBER(3,0), 
	"REQUEST_BODY" CLOB COLLATE "USING_NLS_COMP", 
	"RESPONSE_BODY" CLOB COLLATE "USING_NLS_COMP", 
	"ERROR_MESSAGE" VARCHAR2(1000 CHAR) COLLATE "USING_NLS_COMP", 
	"CREATED_AT" TIMESTAMP (6) NOT NULL ENABLE, 
	"ELAPSED_MS" NUMBER(19,0), 
	 CONSTRAINT "PK_ACC_SIM_HISTORY" PRIMARY KEY ("ID")
  USING INDEX PCTFREE 10 INITRANS 2 MAXTRANS 255 COMPUTE STATISTICS 
  STORAGE(INITIAL 65536 NEXT 1048576 MINEXTENTS 1 MAXEXTENTS 2147483645
  PCTINCREASE 0 FREELISTS 1 FREELIST GROUPS 1
  BUFFER_POOL DEFAULT FLASH_CACHE DEFAULT CELL_FLASH_CACHE DEFAULT)
  TABLESPACE "USERS"  ENABLE
   )  DEFAULT COLLATION "USING_NLS_COMP" SEGMENT CREATION IMMEDIATE 
  PCTFREE 10 PCTUSED 40 INITRANS 1 MAXTRANS 255 
 NOCOMPRESS LOGGING
  STORAGE(INITIAL 65536 NEXT 1048576 MINEXTENTS 1 MAXEXTENTS 2147483645
  PCTINCREASE 0 FREELISTS 1 FREELIST GROUPS 1
  BUFFER_POOL DEFAULT FLASH_CACHE DEFAULT CELL_FLASH_CACHE DEFAULT)
  TABLESPACE "USERS" 
 LOB ("REQUEST_BODY") STORE AS SECUREFILE (
  TABLESPACE "USERS" ENABLE STORAGE IN ROW CHUNK 8192
  NOCACHE LOGGING  NOCOMPRESS  KEEP_DUPLICATES 
  STORAGE(INITIAL 106496 NEXT 1048576 MINEXTENTS 1 MAXEXTENTS 2147483645
  PCTINCREASE 0
  BUFFER_POOL DEFAULT FLASH_CACHE DEFAULT CELL_FLASH_CACHE DEFAULT)) 
 LOB ("RESPONSE_BODY") STORE AS SECUREFILE (
  TABLESPACE "USERS" ENABLE STORAGE IN ROW CHUNK 8192
  NOCACHE LOGGING  NOCOMPRESS  KEEP_DUPLICATES 
  STORAGE(INITIAL 106496 NEXT 1048576 MINEXTENTS 1 MAXEXTENTS 2147483645
  PCTINCREASE 0
  BUFFER_POOL DEFAULT FLASH_CACHE DEFAULT CELL_FLASH_CACHE DEFAULT)) ;


