-- QDITP.AGM_DEVICE_STATUS definition

CREATE TABLE "QDITP"."AGM_DEVICE_STATUS" 
   (	"DEVICE_ID" VARCHAR2(32 CHAR) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"STATION_CODE" VARCHAR2(16 CHAR) COLLATE "USING_NLS_COMP", 
	"LAST_HEARTBEAT_TMS" TIMESTAMP (6) NOT NULL ENABLE, 
	"HEARTBEAT_COUNT" NUMBER(12,0) DEFAULT 1 NOT NULL ENABLE, 
	"ONLINE_FLAG" VARCHAR2(1 CHAR) COLLATE "USING_NLS_COMP" DEFAULT '1' NOT NULL ENABLE, 
	"CREATE_TMS" TIMESTAMP (6) DEFAULT SYSTIMESTAMP NOT NULL ENABLE, 
	"UPDATE_TMS" TIMESTAMP (6) DEFAULT SYSTIMESTAMP NOT NULL ENABLE, 
	 CONSTRAINT "CK_AGM_DEVICE_STATUS_ONLINE" CHECK (ONLINE_FLAG IN ('0', '1')) ENABLE, 
	 CONSTRAINT "PK_AGM_DEVICE_STATUS" PRIMARY KEY ("DEVICE_ID")
  USING INDEX PCTFREE 10 INITRANS 2 MAXTRANS 255 COMPUTE STATISTICS 
  STORAGE(INITIAL 65536 NEXT 1048576 MINEXTENTS 1 MAXEXTENTS 2147483645
  PCTINCREASE 0 FREELISTS 1 FREELIST GROUPS 1
  BUFFER_POOL DEFAULT FLASH_CACHE DEFAULT CELL_FLASH_CACHE DEFAULT)
  TABLESPACE "USERS"  ENABLE
   )  DEFAULT COLLATION "USING_NLS_COMP" SEGMENT CREATION IMMEDIATE 
  PCTFREE 10 PCTUSED 40 INITRANS 1 MAXTRANS 255 
 NOCOMPRESS LOGGING
  STORAGE(INITIAL 65536 NEXT 1048576 MINEXTENTS 1 MAXEXTENTS 2147483645
  PCTINCREASE 0 FREELISTS 1 FREELIST GROUPS 1
  BUFFER_POOL DEFAULT FLASH_CACHE DEFAULT CELL_FLASH_CACHE DEFAULT)
  TABLESPACE "USERS" ;

COMMENT ON COLUMN "QDITP"."AGM_DEVICE_STATUS"."DEVICE_ID" IS '设备号';
   COMMENT ON COLUMN "QDITP"."AGM_DEVICE_STATUS"."STATION_CODE" IS '设备所在车站编码，由 deviceId 前 4 位解析';
   COMMENT ON COLUMN "QDITP"."AGM_DEVICE_STATUS"."LAST_HEARTBEAT_TMS" IS '最近一次心跳时间';
   COMMENT ON COLUMN "QDITP"."AGM_DEVICE_STATUS"."HEARTBEAT_COUNT" IS '累计心跳次数';
   COMMENT ON COLUMN "QDITP"."AGM_DEVICE_STATUS"."ONLINE_FLAG" IS '1 在线，0 离线';
   COMMENT ON TABLE "QDITP"."AGM_DEVICE_STATUS"  IS 'AGM 闸机最新心跳状态，一设备一行，用 MERGE INTO 更新；只存最新状态不存历史';


-- QDITP.ALIPAY_CARD_POOL definition

CREATE TABLE "QDITP"."ALIPAY_CARD_POOL" 
   (	"CARD_ID" VARCHAR2(32) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"THIRD_USER_ID" VARCHAR2(64) COLLATE "USING_NLS_COMP", 
	"STATUS" VARCHAR2(16) COLLATE "USING_NLS_COMP" DEFAULT 'UNALLOCATED' NOT NULL ENABLE, 
	"INSERT_TMS" DATE DEFAULT SYSDATE NOT NULL ENABLE, 
	"REG_TMS" DATE, 
	"DELETE_FLAG" VARCHAR2(1) COLLATE "USING_NLS_COMP" DEFAULT '0' NOT NULL ENABLE, 
	"VERSION" VARCHAR2(32) COLLATE "USING_NLS_COMP" DEFAULT '1' NOT NULL ENABLE, 
	"CREATE_TIME" DATE DEFAULT SYSDATE NOT NULL ENABLE, 
	"UPDATE_TIME" DATE DEFAULT SYSDATE NOT NULL ENABLE, 
	"CREATE_BY" VARCHAR2(32) COLLATE "USING_NLS_COMP", 
	 CONSTRAINT "PK_ALIPAY_CARD_POOL" PRIMARY KEY ("CARD_ID")
  USING INDEX PCTFREE 10 INITRANS 2 MAXTRANS 255 COMPUTE STATISTICS 
  STORAGE(INITIAL 65536 NEXT 1048576 MINEXTENTS 1 MAXEXTENTS 2147483645
  PCTINCREASE 0 FREELISTS 1 FREELIST GROUPS 1
  BUFFER_POOL DEFAULT FLASH_CACHE DEFAULT CELL_FLASH_CACHE DEFAULT)
  TABLESPACE "USERS"  ENABLE
   )  DEFAULT COLLATION "USING_NLS_COMP" SEGMENT CREATION IMMEDIATE 
  PCTFREE 10 PCTUSED 40 INITRANS 1 MAXTRANS 255 
 NOCOMPRESS LOGGING
  STORAGE(INITIAL 65536 NEXT 1048576 MINEXTENTS 1 MAXEXTENTS 2147483645
  PCTINCREASE 0 FREELISTS 1 FREELIST GROUPS 1
  BUFFER_POOL DEFAULT FLASH_CACHE DEFAULT CELL_FLASH_CACHE DEFAULT)
  TABLESPACE "USERS" ;

COMMENT ON COLUMN "QDITP"."ALIPAY_CARD_POOL"."CARD_ID" IS '逻辑卡号（主键）';
   COMMENT ON COLUMN "QDITP"."ALIPAY_CARD_POOL"."THIRD_USER_ID" IS '支付宝用户ID';
   COMMENT ON COLUMN "QDITP"."ALIPAY_CARD_POOL"."STATUS" IS '卡号状态（UNALLOCATED:未分配/ALLOCATED:已分配/USED:已使用）';
   COMMENT ON COLUMN "QDITP"."ALIPAY_CARD_POOL"."INSERT_TMS" IS '插入时间';
   COMMENT ON COLUMN "QDITP"."ALIPAY_CARD_POOL"."REG_TMS" IS '注册时间';
   COMMENT ON COLUMN "QDITP"."ALIPAY_CARD_POOL"."DELETE_FLAG" IS '删除标记（0:正常 1:删除）';
   COMMENT ON COLUMN "QDITP"."ALIPAY_CARD_POOL"."VERSION" IS '乐观锁版本号';
   COMMENT ON COLUMN "QDITP"."ALIPAY_CARD_POOL"."CREATE_TIME" IS '创建时间';
   COMMENT ON COLUMN "QDITP"."ALIPAY_CARD_POOL"."UPDATE_TIME" IS '更新时间';
   COMMENT ON COLUMN "QDITP"."ALIPAY_CARD_POOL"."CREATE_BY" IS '创建人';
   COMMENT ON TABLE "QDITP"."ALIPAY_CARD_POOL"  IS '支付宝卡号池表';


-- QDITP.ALIPAY_PAY_CALLBACK_LOG definition

CREATE TABLE "QDITP"."ALIPAY_PAY_CALLBACK_LOG" 
   (	"CALLBACK_SEQ" VARCHAR2(64) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"ORDER_NO" VARCHAR2(64) COLLATE "USING_NLS_COMP", 
	"CALLBACK_TYPE" VARCHAR2(16) COLLATE "USING_NLS_COMP", 
	"TRANS_STATUS" VARCHAR2(8) COLLATE "USING_NLS_COMP", 
	"CHANNEL_VOUCHER_ID" VARCHAR2(64) COLLATE "USING_NLS_COMP", 
	"TRANS_AMOUNT" VARCHAR2(32) COLLATE "USING_NLS_COMP", 
	"TRANS_TIME" VARCHAR2(32) COLLATE "USING_NLS_COMP", 
	"HANDLE_STATUS" VARCHAR2(16) COLLATE "USING_NLS_COMP", 
	"HANDLE_MSG" VARCHAR2(500) COLLATE "USING_NLS_COMP", 
	"CREATE_TIME" DATE, 
	"UPDATE_TIME" DATE, 
	"TOTAL_AMOUNT" NUMBER(22,0), 
	"TXN_DATE" VARCHAR2(8 CHAR) COLLATE "USING_NLS_COMP", 
	"RAW_BODY" CLOB COLLATE "USING_NLS_COMP", 
	"REFUND_ORDER_NO" VARCHAR2(64 CHAR) COLLATE "USING_NLS_COMP", 
	"REFUND_AMOUNT" NUMBER(22,0), 
	"REFUND_STATUS" VARCHAR2(16 CHAR) COLLATE "USING_NLS_COMP", 
	 CONSTRAINT "PK_ALIPAY_PAY_CALLBACK_LOG" PRIMARY KEY ("CALLBACK_SEQ")
  USING INDEX PCTFREE 10 INITRANS 2 MAXTRANS 255 COMPUTE STATISTICS 
  STORAGE(INITIAL 65536 NEXT 1048576 MINEXTENTS 1 MAXEXTENTS 2147483645
  PCTINCREASE 0 FREELISTS 1 FREELIST GROUPS 1
  BUFFER_POOL DEFAULT FLASH_CACHE DEFAULT CELL_FLASH_CACHE DEFAULT)
  TABLESPACE "USERS"  ENABLE
   )  DEFAULT COLLATION "USING_NLS_COMP" SEGMENT CREATION IMMEDIATE 
  PCTFREE 10 PCTUSED 40 INITRANS 1 MAXTRANS 255 
 NOCOMPRESS LOGGING
  STORAGE(INITIAL 65536 NEXT 1048576 MINEXTENTS 1 MAXEXTENTS 2147483645
  PCTINCREASE 0 FREELISTS 1 FREELIST GROUPS 1
  BUFFER_POOL DEFAULT FLASH_CACHE DEFAULT CELL_FLASH_CACHE DEFAULT)
  TABLESPACE "USERS" 
 LOB ("RAW_BODY") STORE AS SECUREFILE (
  TABLESPACE "USERS" ENABLE STORAGE IN ROW CHUNK 8192
  NOCACHE LOGGING  NOCOMPRESS  KEEP_DUPLICATES 
  STORAGE(INITIAL 106496 NEXT 1048576 MINEXTENTS 1 MAXEXTENTS 2147483645
  PCTINCREASE 0
  BUFFER_POOL DEFAULT FLASH_CACHE DEFAULT CELL_FLASH_CACHE DEFAULT)) ;

COMMENT ON COLUMN "QDITP"."ALIPAY_PAY_CALLBACK_LOG"."TOTAL_AMOUNT" IS '支付中心口径的订单总金额（分），来自 payQuery 同步应答的 totalAmount 键；与本表 TRANS_AMOUNT（支付宝报文原文字符串）不是同一口径，NEVER 合并';
   COMMENT ON COLUMN "QDITP"."ALIPAY_PAY_CALLBACK_LOG"."TXN_DATE" IS '订单日期 yyyyMMdd，取自主表 GATE_TXN_PAY.TXN_DATE，供按账期检索；本表当前未分区，NEVER 把它当分区键用';
   COMMENT ON COLUMN "QDITP"."ALIPAY_PAY_CALLBACK_LOG"."RAW_BODY" IS '回调整包报文原文；2026-09-18 由 VARCHAR2(4000) 改为 CLOB，截断后的报文不再可举证';
   COMMENT ON COLUMN "QDITP"."ALIPAY_PAY_CALLBACK_LOG"."REFUND_ORDER_NO" IS '退款单号，与 ALIPAY_REFUND_LOG.REFUND_ORDER_NO 同源；CALLBACK_TYPE=REFUND 时有值';
   COMMENT ON COLUMN "QDITP"."ALIPAY_PAY_CALLBACK_LOG"."REFUND_AMOUNT" IS '退款金额（分），支付中心回调回传值';
   COMMENT ON COLUMN "QDITP"."ALIPAY_PAY_CALLBACK_LOG"."REFUND_STATUS" IS '退款状态，支付中心回调回传值；当前只落证据不回写业务';
   COMMENT ON TABLE "QDITP"."ALIPAY_PAY_CALLBACK_LOG"  IS '支付宝出行支付结果回调凭据表';


-- QDITP.ALIPAY_PAY_CENTER_MSG_LOG definition

CREATE TABLE "QDITP"."ALIPAY_PAY_CENTER_MSG_LOG" 
   (	"ID" NUMBER(22,0) NOT NULL ENABLE, 
	"ORDER_NO" VARCHAR2(128 CHAR) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"TXN_DATE" VARCHAR2(8 CHAR) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
