COMMENT ON COLUMN "QDITP"."ALIPAY_PAY_CENTER_MSG_LOG"."ORDER_NO" IS '地铁侧订单号，等于 GATE_TXN_PAY.ORDER_NO 与 ALIPAY_PAY_TXN_DETAIL.ORDER_NO';
   COMMENT ON COLUMN "QDITP"."ALIPAY_PAY_CENTER_MSG_LOG"."TXN_DATE" IS '订单日期 yyyyMMdd，月分区键；取自主表，NEVER 用本地当天日期另算';
   COMMENT ON COLUMN "QDITP"."ALIPAY_PAY_CENTER_MSG_LOG"."API_NAME" IS '支付中心接口名：requestPay 扣款，payQuery 支付结果查询，requestRefund 退款申请，refundQuery 退款结果查询';
   COMMENT ON COLUMN "QDITP"."ALIPAY_PAY_CENTER_MSG_LOG"."REQUEST_NO" IS '本次请求的从键：退款类接口填退款单号，支付类接口留空';
   COMMENT ON COLUMN "QDITP"."ALIPAY_PAY_CENTER_MSG_LOG"."SCENE" IS '支付场景，我方送出的请求参数原值';
   COMMENT ON COLUMN "QDITP"."ALIPAY_PAY_CENTER_MSG_LOG"."INDUSTRY_TYPE" IS '行业类型：1地铁，2公交，3打车，4购物';
   COMMENT ON COLUMN "QDITP"."ALIPAY_PAY_CENTER_MSG_LOG"."IP_ADDRESS" IS '发起支付的用户 IP，审计用';
   COMMENT ON COLUMN "QDITP"."ALIPAY_PAY_CENTER_MSG_LOG"."RET_CODE" IS '支付中心本次同步应答的业务码；调用抛异常拿不到应答时留空，成因记在 REMARK';
   COMMENT ON COLUMN "QDITP"."ALIPAY_PAY_CENTER_MSG_LOG"."RET_MSG" IS '支付中心本次同步应答文案；NEVER 把它当 debitRequestResult 直接对外返回';
   COMMENT ON COLUMN "QDITP"."ALIPAY_PAY_CENTER_MSG_LOG"."ELAPSED_MS" IS '本次调用耗时毫秒，用于定位支付中心慢响应';
   COMMENT ON COLUMN "QDITP"."ALIPAY_PAY_CENTER_MSG_LOG"."REQUEST_BODY" IS '我方送出的请求报文原文，MUST 写；支付明细表删掉的 subject / body / authCode / notifyUrl / returnUrl / orderTimeOut 都在这里';
   COMMENT ON COLUMN "QDITP"."ALIPAY_PAY_CENTER_MSG_LOG"."RESPONSE_BODY" IS '支付中心同步应答报文原文；异步回调的原文在 ALIPAY_PAY_CALLBACK_LOG.RAW_BODY，两者不是一回事';
   COMMENT ON TABLE "QDITP"."ALIPAY_PAY_CENTER_MSG_LOG"  IS '支付宝出行渠道我方出网报文留痕表；一次调用一行，追加型流水，无唯一索引，NEVER 拿它推断订单当前状态';


-- QDITP.ALIPAY_PAY_LOG definition

CREATE TABLE "QDITP"."ALIPAY_PAY_LOG" 
   (	"PAY_SEQ" VARCHAR2(64) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"THIRD_USER_ID" VARCHAR2(64) COLLATE "USING_NLS_COMP", 
	"CARD_ID" VARCHAR2(32) COLLATE "USING_NLS_COMP", 
	"ORDER_NO" VARCHAR2(64) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"TRADE_NO" VARCHAR2(64) COLLATE "USING_NLS_COMP", 
	"PAY_AMOUNT" VARCHAR2(16) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"PAY_STATUS" VARCHAR2(16) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"PAY_TYPE" VARCHAR2(16) COLLATE "USING_NLS_COMP", 
	"SCENE" VARCHAR2(32) COLLATE "USING_NLS_COMP", 
	"PAYMENT_VENDOR" VARCHAR2(32) COLLATE "USING_NLS_COMP", 
	"INDUSTRY_TYPE" VARCHAR2(16) COLLATE "USING_NLS_COMP", 
	"SUBJECT" VARCHAR2(128) COLLATE "USING_NLS_COMP", 
	"BODY" VARCHAR2(256) COLLATE "USING_NLS_COMP", 
	"REQUEST_SIGN_SEQ" VARCHAR2(64) COLLATE "USING_NLS_COMP", 
	"ORDER_TIME_OUT" VARCHAR2(16) COLLATE "USING_NLS_COMP", 
	"AUTH_CODE" VARCHAR2(64) COLLATE "USING_NLS_COMP", 
	"NOTIFY_URL" VARCHAR2(256) COLLATE "USING_NLS_COMP", 
	"RETURN_URL" VARCHAR2(256) COLLATE "USING_NLS_COMP", 
	"IP_ADDRESS" VARCHAR2(64) COLLATE "USING_NLS_COMP", 
	"INDUSTRY_DETAIL" CLOB COLLATE "USING_NLS_COMP", 
	"REQUEST_BODY" CLOB COLLATE "USING_NLS_COMP", 
	"RESPONSE_BODY" CLOB COLLATE "USING_NLS_COMP", 
	"RESULT_CODE" VARCHAR2(16) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"RESULT_MSG" VARCHAR2(256) COLLATE "USING_NLS_COMP", 
	"REMARK" VARCHAR2(256) COLLATE "USING_NLS_COMP", 
	"REFUND_STATUS" VARCHAR2(20) COLLATE "USING_NLS_COMP", 
	"REFUND_AMOUNT" VARCHAR2(100) COLLATE "USING_NLS_COMP", 
	"ENTRY_ID" VARCHAR2(128) COLLATE "USING_NLS_COMP", 
	"EXIT_ID" VARCHAR2(128) COLLATE "USING_NLS_COMP", 
	"INVOICE" VARCHAR2(32 CHAR) COLLATE "USING_NLS_COMP", 
	"TRANS_TIME" VARCHAR2(20) COLLATE "USING_NLS_COMP", 
	 CONSTRAINT "PK_ALIPAY_PAY_LOG" PRIMARY KEY ("PAY_SEQ")
  USING INDEX PCTFREE 10 INITRANS 2 MAXTRANS 255 COMPUTE STATISTICS 
  STORAGE(INITIAL 65536 NEXT 1048576 MINEXTENTS 1 MAXEXTENTS 2147483645
  PCTINCREASE 0 FREELISTS 1 FREELIST GROUPS 1
  BUFFER_POOL DEFAULT FLASH_CACHE DEFAULT CELL_FLASH_CACHE DEFAULT)
  TABLESPACE "USERS"  ENABLE
   )  DEFAULT COLLATION "USING_NLS_COMP" SEGMENT CREATION IMMEDIATE 
  PCTFREE 10 PCTUSED 40 INITRANS 1 MAXTRANS 255 
 NOCOMPRESS LOGGING
  STORAGE(INITIAL 65536 NEXT 1048576 MINEXTENTS 1 MAXEXTENTS 2147483645
  PCTINCREASE 0 FREELISTS 1 FREELIST GROUPS 1
  BUFFER_POOL DEFAULT FLASH_CACHE DEFAULT CELL_FLASH_CACHE DEFAULT)
  TABLESPACE "USERS" 
 LOB ("INDUSTRY_DETAIL") STORE AS SECUREFILE (
  TABLESPACE "USERS" ENABLE STORAGE IN ROW CHUNK 8192
  NOCACHE LOGGING  NOCOMPRESS  KEEP_DUPLICATES 
  STORAGE(INITIAL 106496 NEXT 1048576 MINEXTENTS 1 MAXEXTENTS 2147483645
  PCTINCREASE 0
  BUFFER_POOL DEFAULT FLASH_CACHE DEFAULT CELL_FLASH_CACHE DEFAULT)) 
 LOB ("REQUEST_BODY") STORE AS SECUREFILE (
  TABLESPACE "USERS" ENABLE STORAGE IN ROW CHUNK 8192
  NOCACHE LOGGING  NOCOMPRESS  KEEP_DUPLICATES 
  STORAGE(INITIAL 106496 NEXT 1048576 MINEXTENTS 1 MAXEXTENTS 2147483645
  PCTINCREASE 0
  BUFFER_POOL DEFAULT FLASH_CACHE DEFAULT CELL_FLASH_CACHE DEFAULT)) 
 LOB ("RESPONSE_BODY") STORE AS SECUREFILE (
  TABLESPACE "USERS" ENABLE STORAGE IN ROW CHUNK 8192
  NOCACHE LOGGING  NOCOMPRESS  KEEP_DUPLICATES 
  STORAGE(INITIAL 106496 NEXT 1048576 MINEXTENTS 1 MAXEXTENTS 2147483645
  PCTINCREASE 0
  BUFFER_POOL DEFAULT FLASH_CACHE DEFAULT CELL_FLASH_CACHE DEFAULT)) ;

COMMENT ON COLUMN "QDITP"."ALIPAY_PAY_LOG"."PAY_SEQ" IS '支付流水号（主键）';
   COMMENT ON COLUMN "QDITP"."ALIPAY_PAY_LOG"."THIRD_USER_ID" IS '支付宝用户ID';
   COMMENT ON COLUMN "QDITP"."ALIPAY_PAY_LOG"."CARD_ID" IS '逻辑卡号';
   COMMENT ON COLUMN "QDITP"."ALIPAY_PAY_LOG"."ORDER_NO" IS '订单号';
   COMMENT ON COLUMN "QDITP"."ALIPAY_PAY_LOG"."TRADE_NO" IS '支付宝交易号';
   COMMENT ON COLUMN "QDITP"."ALIPAY_PAY_LOG"."PAY_AMOUNT" IS '支付金额（分）';
   COMMENT ON COLUMN "QDITP"."ALIPAY_PAY_LOG"."PAY_STATUS" IS '支付状态（SUCCESS/FAIL）';
   COMMENT ON COLUMN "QDITP"."ALIPAY_PAY_LOG"."PAY_TYPE" IS '支付类型';
   COMMENT ON COLUMN "QDITP"."ALIPAY_PAY_LOG"."SCENE" IS '支付类型/场景';
   COMMENT ON COLUMN "QDITP"."ALIPAY_PAY_LOG"."PAYMENT_VENDOR" IS '支付方式';
   COMMENT ON COLUMN "QDITP"."ALIPAY_PAY_LOG"."INDUSTRY_TYPE" IS '行业类型：1-地铁 2-公交 3-打车 4-购物';
   COMMENT ON COLUMN "QDITP"."ALIPAY_PAY_LOG"."SUBJECT" IS '订单标题';
   COMMENT ON COLUMN "QDITP"."ALIPAY_PAY_LOG"."BODY" IS '订单描述';
   COMMENT ON COLUMN "QDITP"."ALIPAY_PAY_LOG"."REQUEST_SIGN_SEQ" IS '签约流水号（免密场景）';
   COMMENT ON COLUMN "QDITP"."ALIPAY_PAY_LOG"."ORDER_TIME_OUT" IS '订单超时时间（秒）';
   COMMENT ON COLUMN "QDITP"."ALIPAY_PAY_LOG"."AUTH_CODE" IS '授权码';
   COMMENT ON COLUMN "QDITP"."ALIPAY_PAY_LOG"."NOTIFY_URL" IS '回调地址';
   COMMENT ON COLUMN "QDITP"."ALIPAY_PAY_LOG"."RETURN_URL" IS '返回前端页面地址';
   COMMENT ON COLUMN "QDITP"."ALIPAY_PAY_LOG"."IP_ADDRESS" IS '用户IP地址';
   COMMENT ON COLUMN "QDITP"."ALIPAY_PAY_LOG"."INDUSTRY_DETAIL" IS '行业详情，json格式';
   COMMENT ON COLUMN "QDITP"."ALIPAY_PAY_LOG"."REQUEST_BODY" IS '原始请求报文';
   COMMENT ON COLUMN "QDITP"."ALIPAY_PAY_LOG"."RESPONSE_BODY" IS '原始响应报文';
   COMMENT ON COLUMN "QDITP"."ALIPAY_PAY_LOG"."RESULT_CODE" IS '响应码';
   COMMENT ON COLUMN "QDITP"."ALIPAY_PAY_LOG"."RESULT_MSG" IS '响应信息';
   COMMENT ON COLUMN "QDITP"."ALIPAY_PAY_LOG"."REMARK" IS '备注';
   COMMENT ON COLUMN "QDITP"."ALIPAY_PAY_LOG"."ENTRY_ID" IS '进站交易id';
   COMMENT ON COLUMN "QDITP"."ALIPAY_PAY_LOG"."EXIT_ID" IS '出站交易id';
   COMMENT ON COLUMN "QDITP"."ALIPAY_PAY_LOG"."INVOICE" IS '发票状态';
   COMMENT ON COLUMN "QDITP"."ALIPAY_PAY_LOG"."TRANS_TIME" IS '交易时间（yyyy-MM-dd HH:mm:ss）';
   COMMENT ON TABLE "QDITP"."ALIPAY_PAY_LOG"  IS '支付宝支付流水表';


-- QDITP.ALIPAY_PAY_TXN_DETAIL definition

CREATE TABLE "QDITP"."ALIPAY_PAY_TXN_DETAIL" 
   (	"ID" NUMBER(22,0) NOT NULL ENABLE, 
	"ORDER_NO" VARCHAR2(128 CHAR) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"TXN_DATE" VARCHAR2(8 CHAR) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"PAY_STATUS" VARCHAR2(32 CHAR) COLLATE "USING_NLS_COMP" DEFAULT 'INIT' NOT NULL ENABLE, 
	"AMOUNT" NUMBER(22,0) DEFAULT 0 NOT NULL ENABLE, 
	"REFUND_STATUS" VARCHAR2(32 CHAR) COLLATE "USING_NLS_COMP" DEFAULT 'NONE' NOT NULL ENABLE, 
	"REFUND_AMOUNT" NUMBER(22,0) DEFAULT 0 NOT NULL ENABLE, 
	"LAST_REFUND_TIME" TIMESTAMP (6), 
	"PAY_CENTER_ORDER_NO" VARCHAR2(128 CHAR) COLLATE "USING_NLS_COMP", 
	"CHANNEL_ORDER_NO" VARCHAR2(256 CHAR) COLLATE "USING_NLS_COMP", 
	"REQUEST_SIGN_SEQ" VARCHAR2(256 CHAR) COLLATE "USING_NLS_COMP", 
	"CHANNEL_AGREEMENT_NO" VARCHAR2(256 CHAR) COLLATE "USING_NLS_COMP", 
	"REQUEST_COUNT" NUMBER(22,0) DEFAULT 0 NOT NULL ENABLE, 
	"LAST_REQUEST_TIME" TIMESTAMP (6), 
	"NEXT_REQUEST_TIME" TIMESTAMP (6), 
	"INVOICE" VARCHAR2(32 CHAR) COLLATE "USING_NLS_COMP", 
	"CREATE_TIME" TIMESTAMP (6) DEFAULT SYSTIMESTAMP NOT NULL ENABLE, 
	"UPDATE_TIME" TIMESTAMP (6) DEFAULT SYSTIMESTAMP NOT NULL ENABLE, 
	"TRANS_TIME" VARCHAR2(32 CHAR) COLLATE "USING_NLS_COMP", 
	 CONSTRAINT "PK_ALIPAY_PAY_TXN_DETAIL" PRIMARY KEY ("ID")
  USING INDEX PCTFREE 10 INITRANS 2 MAXTRANS 255 COMPUTE STATISTICS 
  STORAGE(INITIAL 65536 NEXT 1048576 MINEXTENTS 1 MAXEXTENTS 2147483645
  PCTINCREASE 0 FREELISTS 1 FREELIST GROUPS 1
  BUFFER_POOL DEFAULT FLASH_CACHE DEFAULT CELL_FLASH_CACHE DEFAULT)
  TABLESPACE "USERS"  ENABLE
   )  DEFAULT COLLATION "USING_NLS_COMP" PCTFREE 10 PCTUSED 40 INITRANS 1 MAXTRANS 255 
  STORAGE(
  BUFFER_POOL DEFAULT FLASH_CACHE DEFAULT CELL_FLASH_CACHE DEFAULT)
  TABLESPACE "USERS" 
  PARTITION BY RANGE ("TXN_DATE") 
 (PARTITION "P202606"  VALUES LESS THAN ('20260701') SEGMENT CREATION DEFERRED 
  PCTFREE 10 PCTUSED 40 INITRANS 1 MAXTRANS 255 
 NOCOMPRESS LOGGING 
  STORAGE(
  BUFFER_POOL DEFAULT FLASH_CACHE DEFAULT CELL_FLASH_CACHE DEFAULT)
  TABLESPACE "USERS" , 
 PARTITION "P202607"  VALUES LESS THAN ('20260801') SEGMENT CREATION DEFERRED 
  PCTFREE 10 PCTUSED 40 INITRANS 1 MAXTRANS 255 
 NOCOMPRESS LOGGING 
  STORAGE(
  BUFFER_POOL DEFAULT FLASH_CACHE DEFAULT CELL_FLASH_CACHE DEFAULT)
  TABLESPACE "USERS" , 
 PARTITION "P202608"  VALUES LESS THAN ('20260901') SEGMENT CREATION DEFERRED 
  PCTFREE 10 PCTUSED 40 INITRANS 1 MAXTRANS 255 
 NOCOMPRESS LOGGING 
  STORAGE(
  BUFFER_POOL DEFAULT FLASH_CACHE DEFAULT CELL_FLASH_CACHE DEFAULT)
  TABLESPACE "USERS" , 
 PARTITION "P202609"  VALUES LESS THAN ('20261001') SEGMENT CREATION IMMEDIATE 
  PCTFREE 10 PCTUSED 40 INITRANS 1 MAXTRANS 255 
 NOCOMPRESS LOGGING 
  STORAGE(INITIAL 8388608 NEXT 1048576 MINEXTENTS 1 MAXEXTENTS 2147483645
  PCTINCREASE 0 FREELISTS 1 FREELIST GROUPS 1
  BUFFER_POOL DEFAULT FLASH_CACHE DEFAULT CELL_FLASH_CACHE DEFAULT)
  TABLESPACE "USERS" , 
 PARTITION "P202610"  VALUES LESS THAN ('20261101') SEGMENT CREATION DEFERRED 
  PCTFREE 10 PCTUSED 40 INITRANS 1 MAXTRANS 255 
 NOCOMPRESS LOGGING 
  STORAGE(
  BUFFER_POOL DEFAULT FLASH_CACHE DEFAULT CELL_FLASH_CACHE DEFAULT)
  TABLESPACE "USERS" , 
 PARTITION "P202611"  VALUES LESS THAN ('20261201') SEGMENT CREATION DEFERRED 
