COMMENT ON COLUMN "QDITP"."ALIPAY_PAY_TXN_DETAIL"."ORDER_NO" IS '地铁侧订单号，等于 GATE_TXN_PAY.ORDER_NO，同时作为支付中心接口的 orderNo；本表唯一的对外查询键';
   COMMENT ON COLUMN "QDITP"."ALIPAY_PAY_TXN_DETAIL"."TXN_DATE" IS '订单日期 yyyyMMdd，月分区键 + 唯一键第二列；取 GATE_TXN_PAY.TXN_DATE，NEVER 用本地当天日期另算';
   COMMENT ON COLUMN "QDITP"."ALIPAY_PAY_TXN_DETAIL"."PAY_STATUS" IS '本笔在支付中心侧的状态：INIT初始化，PROCESSING处理中，SUCCESS成功，FAIL失败，RETRY待重试，CLOSED关闭；订单整体是否扣费成功以 GATE_TXN_PAY.DEBIT_STATUS 为准';
   COMMENT ON COLUMN "QDITP"."ALIPAY_PAY_TXN_DETAIL"."AMOUNT" IS '我方送出的请求支付金额（分），恒有值；本表唯一的金额列，退款可退上限只取它。对端回传的金额在 ALIPAY_PAY_CALLBACK_LOG';
   COMMENT ON COLUMN "QDITP"."ALIPAY_PAY_TXN_DETAIL"."REFUND_STATUS" IS '退款状态：NONE未退款，PROCESSING退款中，PARTIAL部分退款，SUCCESS已全额退款，FAIL退款失败';
   COMMENT ON COLUMN "QDITP"."ALIPAY_PAY_TXN_DETAIL"."REFUND_AMOUNT" IS '已退款总金额（分），由 ALIPAY_REFUND_TXN_DETAIL 重算得出，NEVER 累加写入';
   COMMENT ON COLUMN "QDITP"."ALIPAY_PAY_TXN_DETAIL"."LAST_REFUND_TIME" IS '最近一次退款汇总刷新时间';
   COMMENT ON COLUMN "QDITP"."ALIPAY_PAY_TXN_DETAIL"."PAY_CENTER_ORDER_NO" IS '支付中心支付订单号，来自 requestPay 的同步应答；退款报文的原支付订单号取此列，缺它退款必失败';
   COMMENT ON COLUMN "QDITP"."ALIPAY_PAY_TXN_DETAIL"."CHANNEL_ORDER_NO" IS '渠道订单号，即支付宝交易号（旧表 TRADE_NO）；属当前态关键标识，故留在本表';
   COMMENT ON COLUMN "QDITP"."ALIPAY_PAY_TXN_DETAIL"."REQUEST_SIGN_SEQ" IS '我方签约流水号，取 ALIPAY_SIGN_INFO.AGREEMENT_CODE';
   COMMENT ON COLUMN "QDITP"."ALIPAY_PAY_TXN_DETAIL"."CHANNEL_AGREEMENT_NO" IS '渠道协议号，取 ALIPAY_SIGN_INFO.CHANNEL_AGREEMENT_CODE；与上一列不是同一个号，销卡通知与退款只认这个';
   COMMENT ON COLUMN "QDITP"."ALIPAY_PAY_TXN_DETAIL"."REQUEST_COUNT" IS '已发起支付请求次数；每次出网的请求与应答原文在 ALIPAY_PAY_CENTER_MSG_LOG，一次一行';
   COMMENT ON COLUMN "QDITP"."ALIPAY_PAY_TXN_DETAIL"."NEXT_REQUEST_TIME" IS '下次允许重试支付时间';
   COMMENT ON COLUMN "QDITP"."ALIPAY_PAY_TXN_DETAIL"."INVOICE" IS '发票状态；旧表 33 行实测全为 NULL、从未被写过，本表同样没有写入方，属占位列。接线前 MUST 先确认发票状态归谁维护，NEVER 假定它有值';
   COMMENT ON COLUMN "QDITP"."ALIPAY_PAY_TXN_DETAIL"."TRANS_TIME" IS '支付时刻，统一存14位yyyyMMddHHmmss（2026-09-20起，归一在PayTxnCallbackWriter.normalizeTransTime做）；报文原文留在ALIPAY_PAY_CALLBACK_LOG的TRANS_TIME与RAW_BODY；列仍是VARCHAR2因归一失败时原样入库，NEVER建成DATE也NEVER用TO_DATE查询；支付宝出行记录应答的payOrderNoDate取此列；只由支付回调写入且套NVL';
   COMMENT ON TABLE "QDITP"."ALIPAY_PAY_TXN_DETAIL"  IS '支付宝出行（小程序）渠道支付交易明细表；订单主表是 GATE_TXN_PAY，本表按 ORDER_NO 一对一挂在其上，只装支付侧当前态。报文原文在 ALIPAY_PAY_CENTER_MSG_LOG，对端回调在 ALIPAY_PAY_CALLBACK_LOG';


