	"LAST_REQUEST_TIME" TIMESTAMP (6), 
	"REFUND_TIME" VARCHAR2(28 CHAR) COLLATE "USING_NLS_COMP", 
	"TXN_DATE" VARCHAR2(8 CHAR) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"OPERATOR" VARCHAR2(64 CHAR) COLLATE "USING_NLS_COMP", 
