COMMENT ON COLUMN "QDITP"."ALIPAY_REFUND_TXN_DETAIL"."REFUND_ORDER_NO" IS '内部退款单号，由本模块生成';
   COMMENT ON COLUMN "QDITP"."ALIPAY_REFUND_TXN_DETAIL"."ORDER_NO" IS '原支付订单号，对应 ALIPAY_PAY_TXN_DETAIL.ORDER_NO';
   COMMENT ON COLUMN "QDITP"."ALIPAY_REFUND_TXN_DETAIL"."REFUND_STATUS" IS '退款状态：INIT初始化，PROCESSING处理中，SUCCESS成功，FAIL失败，RETRY待重试，CLOSED关闭；拿不到业务应答时 MUST 保持 PROCESSING，NEVER 置 FAIL';
   COMMENT ON COLUMN "QDITP"."ALIPAY_REFUND_TXN_DETAIL"."REFUND_AMOUNT" IS '退款金额，单位分';
   COMMENT ON COLUMN "QDITP"."ALIPAY_REFUND_TXN_DETAIL"."REQUEST_COUNT" IS '已发起退款请求次数';
   COMMENT ON COLUMN "QDITP"."ALIPAY_REFUND_TXN_DETAIL"."NEXT_REQUEST_TIME" IS '下次允许重试退款时间';
   COMMENT ON COLUMN "QDITP"."ALIPAY_REFUND_TXN_DETAIL"."TXN_DATE" IS '退款发起日期，格式YYYYMMDD，用于月分区与唯一键；与原支付单的 TXN_DATE 各自独立，NEVER 复用原单日期';
   COMMENT ON TABLE "QDITP"."ALIPAY_REFUND_TXN_DETAIL"  IS '支付宝出行渠道退款明细表';


