   COMMENT ON COLUMN "QDITP"."APP_TERMINATION_REQUEST"."CHANNEL_SYNC_STATUS" IS '向账户域清理支付通道的投递状态：PENDING待投递、SUCCESS已清理、FAILED待重试；NULL表示本行早于改造，NEVER被补偿扫描捞取';
   COMMENT ON COLUMN "QDITP"."APP_TERMINATION_REQUEST"."CHANNEL_SYNC_RETRY_COUNT" IS '清理重试次数，达上限后不再扫描、转人工处理';
