   COMMENT ON COLUMN "QDITP"."APP_TERMINATION_REQUEST"."CHANNEL_SYNC_RESULT" IS '最近一次清理的返回码与消息，超长由调用方截断';
   COMMENT ON TABLE "QDITP"."APP_TERMINATION_REQUEST"  IS 'ITP解约申请表';


