-- QDITP.BLACKLIST definition

CREATE TABLE "QDITP"."BLACKLIST" 
   (	"ID" NUMBER(22,0) GENERATED BY DEFAULT AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE, 
	"CARD_ID" VARCHAR2(32 CHAR) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"THIRD_USER_ID" VARCHAR2(16 CHAR) COLLATE "USING_NLS_COMP", 
	"CARD_TYPE" VARCHAR2(8 CHAR) COLLATE "USING_NLS_COMP", 
	"CHANNEL_CODE" VARCHAR2(2 CHAR) COLLATE "USING_NLS_COMP" DEFAULT '99' NOT NULL ENABLE, 
	"BLACK_SOURCE" VARCHAR2(2 CHAR) COLLATE "USING_NLS_COMP" DEFAULT '09' NOT NULL ENABLE, 
	"BLACK_CAUSE" VARCHAR2(2 CHAR) COLLATE "USING_NLS_COMP" DEFAULT '09' NOT NULL ENABLE, 
	"BIZ_NO" VARCHAR2(128 CHAR) COLLATE "USING_NLS_COMP", 
	"REASON" VARCHAR2(1000 CHAR) COLLATE "USING_NLS_COMP", 
	"CREATE_BY" VARCHAR2(32 CHAR) COLLATE "USING_NLS_COMP", 
	"CREATE_TIME" TIMESTAMP (6) DEFAULT SYSTIMESTAMP NOT NULL ENABLE, 
	"CHANNEL_SYNC_STATUS" VARCHAR2(16 CHAR) COLLATE "USING_NLS_COMP", 
	"CHANNEL_SYNC_TIME" TIMESTAMP (6), 
	"CHANNEL_SYNC_RETRY" NUMBER(4,0) DEFAULT 0, 
	"CHANNEL_SYNC_FAIL_REASON" VARCHAR2(500 CHAR) COLLATE "USING_NLS_COMP", 
	"STATUS" VARCHAR2(16) COLLATE "USING_NLS_COMP" DEFAULT 'ACTIVE', 
	"RELEASE_REASON" VARCHAR2(500) COLLATE "USING_NLS_COMP", 
	"RELEASE_BY" VARCHAR2(32) COLLATE "USING_NLS_COMP", 
	 CONSTRAINT "PK_BLACKLIST" PRIMARY KEY ("ID")
  USING INDEX PCTFREE 10 INITRANS 2 MAXTRANS 255 COMPUTE STATISTICS 
  STORAGE(INITIAL 65536 NEXT 1048576 MINEXTENTS 1 MAXEXTENTS 2147483645
  PCTINCREASE 0 FREELISTS 1 FREELIST GROUPS 1
  BUFFER_POOL DEFAULT FLASH_CACHE DEFAULT CELL_FLASH_CACHE DEFAULT)
  TABLESPACE "USERS"  ENABLE, 
	 CONSTRAINT "UK_BLACKLIST_CARD_ID" UNIQUE ("CARD_ID")
  USING INDEX PCTFREE 10 INITRANS 2 MAXTRANS 255 COMPUTE STATISTICS 
  STORAGE(INITIAL 65536 NEXT 1048576 MINEXTENTS 1 MAXEXTENTS 2147483645
  PCTINCREASE 0 FREELISTS 1 FREELIST GROUPS 1
  BUFFER_POOL DEFAULT FLASH_CACHE DEFAULT CELL_FLASH_CACHE DEFAULT)
  TABLESPACE "USERS"  ENABLE
   )  DEFAULT COLLATION "USING_NLS_COMP" SEGMENT CREATION IMMEDIATE 
  PCTFREE 10 PCTUSED 40 INITRANS 1 MAXTRANS 255 
 NOCOMPRESS LOGGING
  STORAGE(INITIAL 65536 NEXT 1048576 MINEXTENTS 1 MAXEXTENTS 2147483645
  PCTINCREASE 0 FREELISTS 1 FREELIST GROUPS 1
  BUFFER_POOL DEFAULT FLASH_CACHE DEFAULT CELL_FLASH_CACHE DEFAULT)
  TABLESPACE "USERS" ;

COMMENT ON COLUMN "QDITP"."BLACKLIST"."ID" IS '主键ID';
   COMMENT ON COLUMN "QDITP"."BLACKLIST"."CARD_ID" IS '卡ID，唯一业务键；查询与解除均以本列为准';
   COMMENT ON COLUMN "QDITP"."BLACKLIST"."THIRD_USER_ID" IS '三方用户ID，审计冗余，不参与命中判定';
   COMMENT ON COLUMN "QDITP"."BLACKLIST"."CARD_TYPE" IS '卡类型编码（票种，如0441），出向通知契约需要';
   COMMENT ON COLUMN "QDITP"."BLACKLIST"."CHANNEL_CODE" IS '业务渠道：01地铁APP，02支付宝，99未知；黑名单域自有编码，与账户域ISSUE_ORG_CODE无对应关系';
   COMMENT ON COLUMN "QDITP"."BLACKLIST"."BLACK_SOURCE" IS '发起方：01系统自动，02渠道通知，09运维手工';
   COMMENT ON COLUMN "QDITP"."BLACKLIST"."BLACK_CAUSE" IS '拉黑原因：01未付费欠费，02挂失补卡，09其他';
   COMMENT ON COLUMN "QDITP"."BLACKLIST"."BIZ_NO" IS '关联业务单号，语义由CHANNEL_CODE与BLACK_SOURCE共同决定，可空';
   COMMENT ON COLUMN "QDITP"."BLACKLIST"."REASON" IS '拉黑备注，自由文本，非判定依据';
   COMMENT ON COLUMN "QDITP"."BLACKLIST"."CREATE_BY" IS '操作者：运维手工记管理员账号，系统触发记服务名';
   COMMENT ON COLUMN "QDITP"."BLACKLIST"."CREATE_TIME" IS '创建时间';
   COMMENT ON COLUMN "QDITP"."BLACKLIST"."CHANNEL_SYNC_STATUS" IS '渠道同步状态：PENDING/SUCCESS/FAILED/REJECTED';
   COMMENT ON COLUMN "QDITP"."BLACKLIST"."CHANNEL_SYNC_TIME" IS '渠道同步时间';
   COMMENT ON COLUMN "QDITP"."BLACKLIST"."CHANNEL_SYNC_RETRY" IS '渠道同步重试次数';
   COMMENT ON COLUMN "QDITP"."BLACKLIST"."CHANNEL_SYNC_FAIL_REASON" IS '渠道同步失败原因';
   COMMENT ON TABLE "QDITP"."BLACKLIST"  IS '黑名单表，只存当前生效记录，解除后整行搬至 BLACKLIST_RELEASED';


