   COMMENT ON COLUMN "QDITP"."BLACKLIST_OPERATE_LOG"."OPERATOR" IS '操作者：运维手工记管理员账号，系统触发记服务名';
   COMMENT ON TABLE "QDITP"."BLACKLIST_OPERATE_LOG"  IS '黑名单操作记录表';


