COMMENT ON COLUMN "QDITP"."DAILY_TICKET_ORDER"."ID" IS '主键ID';
   COMMENT ON COLUMN "QDITP"."DAILY_TICKET_ORDER"."ORDER_NO" IS '日票订单号';
   COMMENT ON COLUMN "QDITP"."DAILY_TICKET_ORDER"."ORDER_TYPE" IS '订单类型，日票固定为1';
   COMMENT ON COLUMN "QDITP"."DAILY_TICKET_ORDER"."THIRD_USER_ID" IS '第三方用户编号';
   COMMENT ON COLUMN "QDITP"."DAILY_TICKET_ORDER"."USER_ID" IS 'APP用户编号';
   COMMENT ON COLUMN "QDITP"."DAILY_TICKET_ORDER"."ORDER_SOURCE" IS '订单来源';
   COMMENT ON COLUMN "QDITP"."DAILY_TICKET_ORDER"."CARD_TYPE" IS 'APP侧卡类型，日票生码时码体票种仍固定为0441';
   COMMENT ON COLUMN "QDITP"."DAILY_TICKET_ORDER"."SHOW_TYPE" IS '展示票类型';
   COMMENT ON COLUMN "QDITP"."DAILY_TICKET_ORDER"."TICKET_NAME" IS '车票名称';
   COMMENT ON COLUMN "QDITP"."DAILY_TICKET_ORDER"."TICKET_PRICE" IS '票价，单位分';
   COMMENT ON COLUMN "QDITP"."DAILY_TICKET_ORDER"."PAY_AMOUNT" IS '实付金额，单位分';
   COMMENT ON COLUMN "QDITP"."DAILY_TICKET_ORDER"."PAY_CHANNEL_CODE" IS '支付渠道编码';
   COMMENT ON COLUMN "QDITP"."DAILY_TICKET_ORDER"."CHANNEL_TYPE" IS 'APP支付场景来源，1转app，2转wap';
   COMMENT ON COLUMN "QDITP"."DAILY_TICKET_ORDER"."PAY_SCENE" IS '支付服务scene字段';
   COMMENT ON COLUMN "QDITP"."DAILY_TICKET_ORDER"."ORDER_STATUS" IS '订单状态：CREATED/PAYING/PAID/CANCELED/REFUNDING/REFUNDED等';
   COMMENT ON COLUMN "QDITP"."DAILY_TICKET_ORDER"."PAY_STATUS" IS '支付状态：INIT/PAYING/PAID/FAIL等';
   COMMENT ON COLUMN "QDITP"."DAILY_TICKET_ORDER"."TRADE_NO" IS '第三方支付交易号';
   COMMENT ON COLUMN "QDITP"."DAILY_TICKET_ORDER"."PAYMENT_ORDER_NO" IS '支付系统订单号';
   COMMENT ON COLUMN "QDITP"."DAILY_TICKET_ORDER"."PAY_DATE" IS '支付完成时间';
   COMMENT ON COLUMN "QDITP"."DAILY_TICKET_ORDER"."CREATE_TIME" IS '创建时间';
   COMMENT ON COLUMN "QDITP"."DAILY_TICKET_ORDER"."UPDATE_TIME" IS '更新时间';
   COMMENT ON COLUMN "QDITP"."DAILY_TICKET_ORDER"."PARENT_ORDER_NO" IS '父单号，旅游票聚合单的子单指向TRAVEL_TICKET_ORDER.ORDER_NO，独立日票为空';
   COMMENT ON COLUMN "QDITP"."DAILY_TICKET_ORDER"."CASH_AMOUNT" IS '支付中心回调回传的实付现金金额（分）；原样落库，不做与总额的匹配校验';
   COMMENT ON COLUMN "QDITP"."DAILY_TICKET_ORDER"."COUPON_AMOUNT" IS '支付中心回调回传的优惠金额（分）；原样落库，不做与总额的匹配校验';
   COMMENT ON TABLE "QDITP"."DAILY_TICKET_ORDER"  IS '日票订单表';


