   COMMENT ON COLUMN "QDITP"."DAILY_TICKET_PAY_LOG"."REQUEST_BODY" IS '请求报文';
   COMMENT ON COLUMN "QDITP"."DAILY_TICKET_PAY_LOG"."RESPONSE_BODY" IS '响应报文';
   COMMENT ON COLUMN "QDITP"."DAILY_TICKET_PAY_LOG"."RESULT_CODE" IS '处理结果码';
   COMMENT ON COLUMN "QDITP"."DAILY_TICKET_PAY_LOG"."RESULT_MSG" IS '处理结果信息';
   COMMENT ON COLUMN "QDITP"."DAILY_TICKET_PAY_LOG"."CREATE_TIME" IS '创建时间';
   COMMENT ON TABLE "QDITP"."DAILY_TICKET_PAY_LOG"  IS '日票支付交互日志表';


