   COMMENT ON COLUMN "QDITP"."DAILY_TICKET_PAY_NOTIFY"."UPDATE_TIME" IS '更新时间';
   COMMENT ON TABLE "QDITP"."DAILY_TICKET_PAY_NOTIFY"  IS 'IF8B-05支付结果通知APP任务表';


