   COMMENT ON COLUMN "QDITP"."DAILY_TICKET_REFUND"."REFUND_ORDER_NO" IS '退款订单号';
   COMMENT ON COLUMN "QDITP"."DAILY_TICKET_REFUND"."REFUND_AMOUNT" IS '退款金额，单位分';
   COMMENT ON COLUMN "QDITP"."DAILY_TICKET_REFUND"."REFUND_STATUS" IS '退款状态：REFUNDING/REFUNDED/FAILED/WAIT_VERIFY等';
