   COMMENT ON COLUMN "QDITP"."DAILY_TICKET_REFUND"."UPDATE_TIME" IS '更新时间';
   COMMENT ON COLUMN "QDITP"."DAILY_TICKET_REFUND"."PLATFORM_REFUND_NO" IS '支付平台退款单号';
   COMMENT ON COLUMN "QDITP"."DAILY_TICKET_REFUND"."REFUND_SOURCE" IS '退款来源：NORMAL普通退款/CANCEL_ORDER取消订单自动退款';
   COMMENT ON TABLE "QDITP"."DAILY_TICKET_REFUND"  IS '日票退款记录表';


