	"STATION_CODE" VARCHAR2(16 CHAR) COLLATE "USING_NLS_COMP", 
	"LAST_HEARTBEAT_TMS" TIMESTAMP (6) NOT NULL ENABLE, 
	"HEARTBEAT_COUNT" NUMBER(12,0) DEFAULT 1 NOT NULL ENABLE, 
	"ONLINE_FLAG" VARCHAR2(1 CHAR) COLLATE "USING_NLS_COMP" DEFAULT '1' NOT NULL ENABLE, 
	"CREATE_TMS" TIMESTAMP (6) DEFAULT SYSTIMESTAMP NOT NULL ENABLE, 
	"UPDATE_TMS" TIMESTAMP (6) DEFAULT SYSTIMESTAMP NOT NULL ENABLE, 
	 CONSTRAINT "PK_F2F_DEVICE_STATUS" PRIMARY KEY ("CHANNEL", "DEVICE_ID")
  USING INDEX PCTFREE 10 INITRANS 2 MAXTRANS 255 COMPUTE STATISTICS 
  STORAGE(INITIAL 65536 NEXT 1048576 MINEXTENTS 1 MAXEXTENTS 2147483645
  PCTINCREASE 0 FREELISTS 1 FREELIST GROUPS 1
  BUFFER_POOL DEFAULT FLASH_CACHE DEFAULT CELL_FLASH_CACHE DEFAULT)
  TABLESPACE "USERS"  ENABLE
   )  DEFAULT COLLATION "USING_NLS_COMP" SEGMENT CREATION IMMEDIATE 
  PCTFREE 10 PCTUSED 40 INITRANS 1 MAXTRANS 255 
 NOCOMPRESS LOGGING
  STORAGE(INITIAL 65536 NEXT 1048576 MINEXTENTS 1 MAXEXTENTS 2147483645
  PCTINCREASE 0 FREELISTS 1 FREELIST GROUPS 1
  BUFFER_POOL DEFAULT FLASH_CACHE DEFAULT CELL_FLASH_CACHE DEFAULT)
  TABLESPACE "USERS" ;

COMMENT ON COLUMN "QDITP"."F2F_DEVICE_STATUS"."ONLINE_FLAG" IS '1在线，0离线；由扫表按LAST_HEARTBEAT_TMS超时判定';
   COMMENT ON TABLE "QDITP"."F2F_DEVICE_STATUS"  IS '设备最新心跳状态，一设备一行，用MERGE INTO更新；规格要求每1分钟上报，ITP确认设备正常。只存最新状态不存历史';


-- QDITP.F2F_NOTIFY_TASK definition

CREATE TABLE "QDITP"."F2F_NOTIFY_TASK" 
   (	"ID" NUMBER(22,0) GENERATED BY DEFAULT AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE, 
	"NOTIFY_TYPE" VARCHAR2(24 CHAR) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"TARGET" VARCHAR2(16 CHAR) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"ORDER_NO" VARCHAR2(64 CHAR) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"REFUND_NO" VARCHAR2(64 CHAR) COLLATE "USING_NLS_COMP", 
	"NOTIFY_STATUS" VARCHAR2(16 CHAR) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"PAYLOAD" CLOB COLLATE "USING_NLS_COMP", 
	"RETRY_TIMES" NUMBER(2,0) DEFAULT 0 NOT NULL ENABLE, 
	"MAX_RETRY_TIMES" NUMBER(2,0) DEFAULT 5 NOT NULL ENABLE, 
	"NEXT_RETRY_TMS" TIMESTAMP (6), 
	"LAST_ERROR" VARCHAR2(512 CHAR) COLLATE "USING_NLS_COMP", 
	"SUCCESS_TMS" TIMESTAMP (6), 
	"CREATE_TMS" TIMESTAMP (6) DEFAULT SYSTIMESTAMP NOT NULL ENABLE, 
	"UPDATE_TMS" TIMESTAMP (6) DEFAULT SYSTIMESTAMP NOT NULL ENABLE, 
	 CONSTRAINT "CK_F2F_NOTIFY_TYPE" CHECK (NOTIFY_TYPE IN (
        'TAKE_TICKET_OK', 'TAKE_TICKET_FAIL', 'REFUND_RESULT', 'PAY_RESULT')) ENABLE, 
	 CONSTRAINT "CK_F2F_NOTIFY_TARGET" CHECK (TARGET IN ('APP')) ENABLE, 
	 CONSTRAINT "CK_F2F_NOTIFY_STATUS" CHECK (NOTIFY_STATUS IN ('PENDING', 'SUCCESS', 'FAILED', 'GIVEUP')) ENABLE, 
	 CONSTRAINT "PK_F2F_NOTIFY_TASK" PRIMARY KEY ("ID")
  USING INDEX PCTFREE 10 INITRANS 2 MAXTRANS 255 COMPUTE STATISTICS 
  STORAGE(INITIAL 65536 NEXT 1048576 MINEXTENTS 1 MAXEXTENTS 2147483645
  PCTINCREASE 0 FREELISTS 1 FREELIST GROUPS 1
  BUFFER_POOL DEFAULT FLASH_CACHE DEFAULT CELL_FLASH_CACHE DEFAULT)
  TABLESPACE "USERS"  ENABLE
   )  DEFAULT COLLATION "USING_NLS_COMP" SEGMENT CREATION IMMEDIATE 
  PCTFREE 10 PCTUSED 40 INITRANS 1 MAXTRANS 255 
 NOCOMPRESS LOGGING
  STORAGE(INITIAL 65536 NEXT 1048576 MINEXTENTS 1 MAXEXTENTS 2147483645
  PCTINCREASE 0 FREELISTS 1 FREELIST GROUPS 1
  BUFFER_POOL DEFAULT FLASH_CACHE DEFAULT CELL_FLASH_CACHE DEFAULT)
  TABLESPACE "USERS" 
 LOB ("PAYLOAD") STORE AS SECUREFILE (
  TABLESPACE "USERS" ENABLE STORAGE IN ROW CHUNK 8192
  NOCACHE LOGGING  NOCOMPRESS  KEEP_DUPLICATES 
  STORAGE(INITIAL 106496 NEXT 1048576 MINEXTENTS 1 MAXEXTENTS 2147483645
  PCTINCREASE 0
  BUFFER_POOL DEFAULT FLASH_CACHE DEFAULT CELL_FLASH_CACHE DEFAULT)) ;

COMMENT ON COLUMN "QDITP"."F2F_NOTIFY_TASK"."TARGET" IS '通知目标，当前仅APP。旧实现三张表均为tbl_notice_app_*，无向BOM/TVM的出向通知；新增目标MUST先确认对端有接收接口，NEVER先放开CHECK再找场景';
   COMMENT ON COLUMN "QDITP"."F2F_NOTIFY_TASK"."NOTIFY_STATUS" IS 'GIVEUP表示超过最大重试次数放弃，需人工介入，不再扫表';
   COMMENT ON COLUMN "QDITP"."F2F_NOTIFY_TASK"."NEXT_RETRY_TMS" IS '下次重试时间，退避策略由应用计算后写入，扫表只按此字段取';
   COMMENT ON TABLE "QDITP"."F2F_NOTIFY_TASK"  IS '出向通知任务，替代原三张Notice表；对应IF8B-04/05/06/07';


-- QDITP.F2F_ORDER definition

CREATE TABLE "QDITP"."F2F_ORDER" 
   (	"ID" NUMBER(22,0) GENERATED BY DEFAULT AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE, 
	"ORDER_NO" VARCHAR2(64 CHAR) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
