	"SINGLE_TICKET_TYPE" VARCHAR2(1 CHAR) COLLATE "USING_NLS_COMP", 
	"ENTRY_STATION_CODE" VARCHAR2(16 CHAR) COLLATE "USING_NLS_COMP", 
	"EXIT_STATION_CODE" VARCHAR2(16 CHAR) COLLATE "USING_NLS_COMP", 
