	"SUSPECT_SLIP_NO" VARCHAR2(64 CHAR) COLLATE "USING_NLS_COMP", 
	"QRCODE_GEN_DATE" VARCHAR2(14 CHAR) COLLATE "USING_NLS_COMP", 
	"RANDOM_FACT" VARCHAR2(32 CHAR) COLLATE "USING_NLS_COMP", 
	"ACTIVATE_FLAG" VARCHAR2(1 CHAR) COLLATE "USING_NLS_COMP" DEFAULT '0' NOT NULL ENABLE, 
	"ACTIVATE_DEVICE_ID" VARCHAR2(32 CHAR) COLLATE "USING_NLS_COMP", 
	"ACTIVATE_TMS" TIMESTAMP (6), 
	"EXPIRE_TMS" TIMESTAMP (6), 
	"PAID_TMS" TIMESTAMP (6), 
	"FULFILL_TMS" TIMESTAMP (6), 
	"CREATE_TMS" TIMESTAMP (6) DEFAULT SYSTIMESTAMP NOT NULL ENABLE, 
	"UPDATE_TMS" TIMESTAMP (6) DEFAULT SYSTIMESTAMP NOT NULL ENABLE, 
	"REMARK" VARCHAR2(512 CHAR) COLLATE "USING_NLS_COMP", 
	"REFUND_STATUS" VARCHAR2(16 CHAR) COLLATE "USING_NLS_COMP" DEFAULT 'NONE' NOT NULL ENABLE, 
	"REFUND_AMOUNT" NUMBER(12,0) DEFAULT 0 NOT NULL ENABLE, 
	"LAST_REFUND_TMS" TIMESTAMP (6), 
	"TICKET_PHYSICS_NUM" VARCHAR2(64 CHAR) COLLATE "USING_NLS_COMP", 
	 CONSTRAINT "CK_F2F_ORDER_CHANNEL" CHECK (CHANNEL IN ('01', '02', '03')) ENABLE, 
	 CONSTRAINT "CK_F2F_ORDER_BIZ" CHECK (BIZ_TYPE IN ('01', '02', '03', '04')) ENABLE, 
	 CONSTRAINT "CK_F2F_ORDER_STATUS" CHECK (ORDER_STATUS IN (
        'CREATED', 'PAYING', 'PAID', 'FULFILLED', 'FULFILL_FAILED',
        'TOPUP_SUSPECT', 'PAY_FAILED', 'EXPIRED', 'REFUNDING', 'REFUNDED', 'CANCELED')) ENABLE, 
	 CONSTRAINT "CK_F2F_ORDER_AMOUNT" CHECK (ORDER_AMOUNT >= 0) ENABLE, 
	 CONSTRAINT "PK_F2F_ORDER" PRIMARY KEY ("ID")
  USING INDEX PCTFREE 10 INITRANS 2 MAXTRANS 255 COMPUTE STATISTICS 
  STORAGE(INITIAL 65536 NEXT 1048576 MINEXTENTS 1 MAXEXTENTS 2147483645
  PCTINCREASE 0 FREELISTS 1 FREELIST GROUPS 1
  BUFFER_POOL DEFAULT FLASH_CACHE DEFAULT CELL_FLASH_CACHE DEFAULT)
  TABLESPACE "USERS"  ENABLE, 
	 CONSTRAINT "CK_F2F_ORDER_REFUND_STATUS" CHECK (REFUND_STATUS IN ('NONE', 'PARTIAL', 'SUCCESS')) ENABLE
   )  DEFAULT COLLATION "USING_NLS_COMP" PCTFREE 10 PCTUSED 40 INITRANS 1 MAXTRANS 255 
  STORAGE(
  BUFFER_POOL DEFAULT FLASH_CACHE DEFAULT CELL_FLASH_CACHE DEFAULT)
  TABLESPACE "USERS" 
  PARTITION BY RANGE ("CREATE_TMS") INTERVAL (NUMTOYMINTERVAL(1, 'MONTH')) 
 (PARTITION "P_F2F_ORDER_INIT"  VALUES LESS THAN (TIMESTAMP' 2026-10-01 00:00:00') SEGMENT CREATION IMMEDIATE 
  PCTFREE 10 PCTUSED 40 INITRANS 1 MAXTRANS 255 
 NOCOMPRESS LOGGING 
  STORAGE(INITIAL 8388608 NEXT 1048576 MINEXTENTS 1 MAXEXTENTS 2147483645
  PCTINCREASE 0 FREELISTS 1 FREELIST GROUPS 1
  BUFFER_POOL DEFAULT FLASH_CACHE DEFAULT CELL_FLASH_CACHE DEFAULT)
  TABLESPACE "USERS" ) ;

COMMENT ON COLUMN "QDITP"."F2F_ORDER"."ORDER_NO" IS 'ITP订单号，含版本标识位F2';
   COMMENT ON COLUMN "QDITP"."F2F_ORDER"."CHANNEL" IS '受理渠道：01-APP，02-TVM，03-BOM。STT未接入且编码口径未定（DeviceTypeEnum为14、BaseRequestDTO注释为07），确认后再放开CHECK约束';
   COMMENT ON COLUMN "QDITP"."F2F_ORDER"."BIZ_TYPE" IS '业务类型：01-购票，02-充值，03-取票，04-非现金收款';
   COMMENT ON COLUMN "QDITP"."F2F_ORDER"."TRANS_TYPE" IS 'BOM交易类型：02超时更新，03超程更新，04未出站更新，05无入站更新，06退卡退票，22充值，2A黑名单锁定，2B锁定解除，42行政处理';
   COMMENT ON COLUMN "QDITP"."F2F_ORDER"."ADMIN_TRANS_TYPE" IS 'TRANS_TYPE=42时必填，行政交易类型01~0A';
   COMMENT ON COLUMN "QDITP"."F2F_ORDER"."ORDER_STATUS" IS '内部状态机，不等于对外paymentResult';
   COMMENT ON COLUMN "QDITP"."F2F_ORDER"."ORDER_AMOUNT" IS '订单总金额，单位分';
   COMMENT ON COLUMN "QDITP"."F2F_ORDER"."DEVICE_SEQ" IS '终端设备流水号，BOM传bomOptSeq，TVM不传；与CHANNEL+DEVICE_ID构成防重下单键';
   COMMENT ON COLUMN "QDITP"."F2F_ORDER"."TICKET_PRICE" IS '单张票价，单位分';
   COMMENT ON COLUMN "QDITP"."F2F_ORDER"."SINGLE_TICKET_TYPE" IS '0-按站点购票，1-按固定票价购票';
   COMMENT ON COLUMN "QDITP"."F2F_ORDER"."CARD_BEFORE_AMOUNT" IS '充值前卡内余额，单位分，用于充值限额校验';
   COMMENT ON COLUMN "QDITP"."F2F_ORDER"."SUSPECT_SLIP_NO" IS 'TVM充值存疑时打印的故障单号，BOM凭此号查询';
   COMMENT ON COLUMN "QDITP"."F2F_ORDER"."RANDOM_FACT" IS '取票二维码随机因子，长度32';
   COMMENT ON COLUMN "QDITP"."F2F_ORDER"."ACTIVATE_DEVICE_ID" IS '取票订单已被哪台设备激活，非空即锁定，其他设备查询返回2008';
   COMMENT ON COLUMN "QDITP"."F2F_ORDER"."EXPIRE_TMS" IS '二维码失效时间，创建时间加180秒';
   COMMENT ON COLUMN "QDITP"."F2F_ORDER"."REFUND_STATUS" IS '退款汇总状态：NONE未退，PARTIAL部分退，SUCCESS全额退。与ORDER_STATUS正交，退款不改支付/履约主状态';
   COMMENT ON COLUMN "QDITP"."F2F_ORDER"."REFUND_AMOUNT" IS '已成功退款总额（分），由F2F_REFUND中REFUND_STATUS=SUCCESS的行重算得出，NEVER累加';
   COMMENT ON COLUMN "QDITP"."F2F_ORDER"."LAST_REFUND_TMS" IS '最后一次退款汇总重算时刻';
   COMMENT ON COLUMN "QDITP"."F2F_ORDER"."TICKET_PHYSICS_NUM" IS '物理卡号，设备按IF2A-06/07/09规格上送、我方原样留证；仅充值单有值，单程票与非现金收款为空。与CARD_ID（逻辑卡号）不同源，NEVER互换';
   COMMENT ON TABLE "QDITP"."F2F_ORDER"  IS '当面付收款单主表';


-- QDITP.F2F_PAYMENT definition

CREATE TABLE "QDITP"."F2F_PAYMENT" 
   (	"ID" NUMBER(22,0) GENERATED BY DEFAULT AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE, 
	"ORDER_NO" VARCHAR2(64 CHAR) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"ATTEMPT_NO" NUMBER(4,0) NOT NULL ENABLE, 
	"PAY_SCENE" VARCHAR2(8 CHAR) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"PAY_STATUS" VARCHAR2(16 CHAR) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"PAY_AMOUNT" NUMBER(12,0) NOT NULL ENABLE, 
	"PAY_TYPE" VARCHAR2(1 CHAR) COLLATE "USING_NLS_COMP", 
	"AUTH_CODE" VARCHAR2(128 CHAR) COLLATE "USING_NLS_COMP", 
	"PAYMENT_VENDOR" VARCHAR2(8 CHAR) COLLATE "USING_NLS_COMP", 
	"PAY_CHANNEL_CODE" VARCHAR2(8 CHAR) COLLATE "USING_NLS_COMP", 
	"PAY_URL" VARCHAR2(512 CHAR) COLLATE "USING_NLS_COMP", 
	"PAY_CENTER_ORDER_NO" VARCHAR2(64 CHAR) COLLATE "USING_NLS_COMP", 
	"CHANNEL_ORDER_NO" VARCHAR2(64 CHAR) COLLATE "USING_NLS_COMP", 
	"REQUEST_BODY" CLOB COLLATE "USING_NLS_COMP", 
	"RESPONSE_BODY" CLOB COLLATE "USING_NLS_COMP", 
	"RET_CODE" VARCHAR2(16 CHAR) COLLATE "USING_NLS_COMP", 
	"RET_MSG" VARCHAR2(512 CHAR) COLLATE "USING_NLS_COMP", 
	"COST_MS" NUMBER(10,0), 
	"REQUEST_TMS" TIMESTAMP (6) DEFAULT SYSTIMESTAMP NOT NULL ENABLE, 
	"FINISH_TMS" TIMESTAMP (6), 
	"CREATE_TMS" TIMESTAMP (6) DEFAULT SYSTIMESTAMP NOT NULL ENABLE, 
	"UPDATE_TMS" TIMESTAMP (6) DEFAULT SYSTIMESTAMP NOT NULL ENABLE, 
	"CASH_AMOUNT" NUMBER(12,0), 
	"COUPON_AMOUNT" NUMBER(12,0), 
	 CONSTRAINT "CK_F2F_PAY_SCENE" CHECK (PAY_SCENE IN ('qrcode', 'scan', 'app')) ENABLE, 
	 CONSTRAINT "CK_F2F_PAY_STATUS" CHECK (PAY_STATUS IN ('INIT', 'PROCESSING', 'SUCCESS', 'FAILED', 'UNKNOWN')) ENABLE, 
	 CONSTRAINT "PK_F2F_PAYMENT" PRIMARY KEY ("ID")
  USING INDEX PCTFREE 10 INITRANS 2 MAXTRANS 255 COMPUTE STATISTICS 
  STORAGE(INITIAL 65536 NEXT 1048576 MINEXTENTS 1 MAXEXTENTS 2147483645
  PCTINCREASE 0 FREELISTS 1 FREELIST GROUPS 1
  BUFFER_POOL DEFAULT FLASH_CACHE DEFAULT CELL_FLASH_CACHE DEFAULT)
  TABLESPACE "USERS"  ENABLE
   )  DEFAULT COLLATION "USING_NLS_COMP" PCTFREE 10 PCTUSED 40 INITRANS 1 MAXTRANS 255 
  STORAGE(
  BUFFER_POOL DEFAULT FLASH_CACHE DEFAULT CELL_FLASH_CACHE DEFAULT)
  TABLESPACE "USERS" 
 LOB ("REQUEST_BODY") STORE AS SECUREFILE (
  ENABLE STORAGE IN ROW CHUNK 8192
  NOCACHE LOGGING  NOCOMPRESS  KEEP_DUPLICATES 
  STORAGE(
  BUFFER_POOL DEFAULT FLASH_CACHE DEFAULT CELL_FLASH_CACHE DEFAULT)) 
 LOB ("RESPONSE_BODY") STORE AS SECUREFILE (
  ENABLE STORAGE IN ROW CHUNK 8192
  NOCACHE LOGGING  NOCOMPRESS  KEEP_DUPLICATES 
  STORAGE(
  BUFFER_POOL DEFAULT FLASH_CACHE DEFAULT CELL_FLASH_CACHE DEFAULT)) 
  PARTITION BY RANGE ("CREATE_TMS") INTERVAL (NUMTOYMINTERVAL(1, 'MONTH')) 
 (PARTITION "P_F2F_PAYMENT_INIT"  VALUES LESS THAN (TIMESTAMP' 2026-10-01 00:00:00') SEGMENT CREATION IMMEDIATE 
  PCTFREE 10 PCTUSED 40 INITRANS 1 MAXTRANS 255 
 NOCOMPRESS LOGGING 
  STORAGE(INITIAL 8388608 NEXT 1048576 MINEXTENTS 1 MAXEXTENTS 2147483645
  PCTINCREASE 0 FREELISTS 1 FREELIST GROUPS 1
  BUFFER_POOL DEFAULT FLASH_CACHE DEFAULT CELL_FLASH_CACHE DEFAULT)
  TABLESPACE "USERS" 
 LOB ("REQUEST_BODY") STORE AS SECUREFILE (
  TABLESPACE "USERS" ENABLE STORAGE IN ROW CHUNK 8192
  NOCACHE LOGGING  NOCOMPRESS  KEEP_DUPLICATES 
  STORAGE(INITIAL 8388608 NEXT 1048576 MINEXTENTS 1 MAXEXTENTS 2147483645
  PCTINCREASE 0
  BUFFER_POOL DEFAULT FLASH_CACHE DEFAULT CELL_FLASH_CACHE DEFAULT)) 
 LOB ("RESPONSE_BODY") STORE AS SECUREFILE (
  TABLESPACE "USERS" ENABLE STORAGE IN ROW CHUNK 8192
  NOCACHE LOGGING  NOCOMPRESS  KEEP_DUPLICATES 
  STORAGE(INITIAL 8388608 NEXT 1048576 MINEXTENTS 1 MAXEXTENTS 2147483645
  PCTINCREASE 0
  BUFFER_POOL DEFAULT FLASH_CACHE DEFAULT CELL_FLASH_CACHE DEFAULT)) ) ;

COMMENT ON COLUMN "QDITP"."F2F_PAYMENT"."ATTEMPT_NO" IS '同一订单内的尝试序号，从1递增';
   COMMENT ON COLUMN "QDITP"."F2F_PAYMENT"."PAY_SCENE" IS 'qrcode-设备拉码用户扫，scan-主动扫用户付款码，app-APP内支付';
   COMMENT ON COLUMN "QDITP"."F2F_PAYMENT"."PAY_STATUS" IS 'UNKNOWN表示对端未明确应答，需靠查询接口收口，不得直接判失败';
   COMMENT ON COLUMN "QDITP"."F2F_PAYMENT"."PAY_TYPE" IS '0-本地拼聚合码URL不调支付中心，其他-调支付中心预下单';
   COMMENT ON COLUMN "QDITP"."F2F_PAYMENT"."AUTH_CODE" IS '用户付款码，仅PAY_SCENE=scan时有值';
   COMMENT ON COLUMN "QDITP"."F2F_PAYMENT"."PAY_URL" IS '返回给设备显示为二维码的完整字符串，设备不解析';
   COMMENT ON COLUMN "QDITP"."F2F_PAYMENT"."COST_MS" IS '本次与支付中心交互耗时毫秒，用于排查虚拟线程pin与超时';
   COMMENT ON COLUMN "QDITP"."F2F_PAYMENT"."CASH_AMOUNT" IS '支付中心回调回传的实付现金金额（分）；原样落库，不做与订单金额的匹配校验';
   COMMENT ON COLUMN "QDITP"."F2F_PAYMENT"."COUPON_AMOUNT" IS '支付中心回调回传的优惠金额（分）；原样落库，不做与订单金额的匹配校验';
   COMMENT ON TABLE "QDITP"."F2F_PAYMENT"  IS '与支付中心的支付交互流水，一行一次尝试';


-- QDITP.F2F_REFUND definition

CREATE TABLE "QDITP"."F2F_REFUND" 
   (	"ID" NUMBER(22,0) GENERATED BY DEFAULT AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE, 
	"REFUND_NO" VARCHAR2(64 CHAR) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"ORIG_ORDER_NO" VARCHAR2(64 CHAR) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"TICKET_LOGIC_NUM" VARCHAR2(64 CHAR) COLLATE "USING_NLS_COMP", 
	"REFUND_SOURCE" VARCHAR2(24 CHAR) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"REFUND_STATUS" VARCHAR2(16 CHAR) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"REFUND_NUM" NUMBER(4,0), 
	"REFUND_AMOUNT" NUMBER(12,0) NOT NULL ENABLE, 
	"REFUND_REASON" VARCHAR2(256 CHAR) COLLATE "USING_NLS_COMP", 
	"OPERATOR_ID" VARCHAR2(32 CHAR) COLLATE "USING_NLS_COMP", 
	"DEVICE_ID" VARCHAR2(32 CHAR) COLLATE "USING_NLS_COMP", 
	"TRANS_TYPE" VARCHAR2(2 CHAR) COLLATE "USING_NLS_COMP", 
	"ORIG_TRANS_DATE" VARCHAR2(14 CHAR) COLLATE "USING_NLS_COMP", 
	"PAY_CENTER_REFUND_NO" VARCHAR2(64 CHAR) COLLATE "USING_NLS_COMP", 
	"RETRY_TIMES" NUMBER(2,0) DEFAULT 0 NOT NULL ENABLE, 
	"FAIL_REASON" VARCHAR2(512 CHAR) COLLATE "USING_NLS_COMP", 
	"REQUEST_TMS" TIMESTAMP (6) DEFAULT SYSTIMESTAMP NOT NULL ENABLE, 
	"FINISH_TMS" TIMESTAMP (6), 
	"CREATE_TMS" TIMESTAMP (6) DEFAULT SYSTIMESTAMP NOT NULL ENABLE, 
	"UPDATE_TMS" TIMESTAMP (6) DEFAULT SYSTIMESTAMP NOT NULL ENABLE, 
	"NEXT_QUERY_TMS" TIMESTAMP (6) DEFAULT SYSTIMESTAMP NOT NULL ENABLE, 
	 CONSTRAINT "CK_F2F_REFUND_SOURCE" CHECK (REFUND_SOURCE IN (
        'TAKE_TICKET_FAIL', 'BOM_ORIGINAL', 'APP_REQUEST', 'DAILY_BATCH', 'TOPUP_FAIL', 'PAGE_MANUAL', 'TVM_REQUEST')) ENABLE, 
	 CONSTRAINT "CK_F2F_REFUND_AMOUNT" CHECK (REFUND_AMOUNT > 0) ENABLE, 
	 CONSTRAINT "PK_F2F_REFUND" PRIMARY KEY ("ID")
  USING INDEX PCTFREE 10 INITRANS 2 MAXTRANS 255 COMPUTE STATISTICS 
  STORAGE(INITIAL 65536 NEXT 1048576 MINEXTENTS 1 MAXEXTENTS 2147483645
  PCTINCREASE 0 FREELISTS 1 FREELIST GROUPS 1
  BUFFER_POOL DEFAULT FLASH_CACHE DEFAULT CELL_FLASH_CACHE DEFAULT)
  TABLESPACE "USERS"  ENABLE, 
	 CONSTRAINT "CK_F2F_REFUND_STATUS" CHECK (REFUND_STATUS IN ('INIT', 'PROCESSING', 'SUCCESS', 'FAILED', 'MANUAL')) ENABLE
   )  DEFAULT COLLATION "USING_NLS_COMP" SEGMENT CREATION IMMEDIATE 
  PCTFREE 10 PCTUSED 40 INITRANS 1 MAXTRANS 255 
 NOCOMPRESS LOGGING
  STORAGE(INITIAL 65536 NEXT 1048576 MINEXTENTS 1 MAXEXTENTS 2147483645
  PCTINCREASE 0 FREELISTS 1 FREELIST GROUPS 1
  BUFFER_POOL DEFAULT FLASH_CACHE DEFAULT CELL_FLASH_CACHE DEFAULT)
  TABLESPACE "USERS" ;

COMMENT ON COLUMN "QDITP"."F2F_REFUND"."TICKET_LOGIC_NUM" IS '按票退时填；整单退时为空，唯一索引用NVL占位避免多笔整单退绕过约束';
   COMMENT ON COLUMN "QDITP"."F2F_REFUND"."REFUND_SOURCE" IS 'TAKE_TICKET_FAIL出票故障自动退，BOM_ORIGINAL单程票原路退，APP_REQUEST用户主动退，DAILY_BATCH每日批量退未取票，TOPUP_FAIL充值失败退，PAGE_MANUAL运营端手工退，TVM_REQUEST设备侧requestRefund发起';
   COMMENT ON COLUMN "QDITP"."F2F_REFUND"."REFUND_AMOUNT" IS '退款金额，单位分；出票故障场景等于（订单张数减实际张数）乘单张票价';
   COMMENT ON COLUMN "QDITP"."F2F_REFUND"."RETRY_TIMES" IS '向支付中心发起退款的重试次数';
   COMMENT ON COLUMN "QDITP"."F2F_REFUND"."NEXT_QUERY_TMS" IS '下次允许向支付中心发起退款查询的时刻，扫表谓词就是它；由指数退避计算';
   COMMENT ON TABLE "QDITP"."F2F_REFUND"  IS '退款单，四类来源共用；UK_F2F_REFUND_IDEM是防重复退款的根本手段';


-- QDITP.F2F_RESULT_REPORT definition

CREATE TABLE "QDITP"."F2F_RESULT_REPORT" 
   (	"ID" NUMBER(22,0) GENERATED BY DEFAULT AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE, 
	"REPORT_TYPE" VARCHAR2(24 CHAR) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"ORDER_NO" VARCHAR2(64 CHAR) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"CHANNEL" VARCHAR2(2 CHAR) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"DEVICE_ID" VARCHAR2(32 CHAR) COLLATE "USING_NLS_COMP", 
	"OPERATOR_ID" VARCHAR2(32 CHAR) COLLATE "USING_NLS_COMP", 
	"ORDER_TICKET_NUM" NUMBER(4,0), 
	"ACTUAL_TICKET_NUM" NUMBER(4,0), 
	"TOPUP_STATUS" VARCHAR2(2 CHAR) COLLATE "USING_NLS_COMP", 
	"OPT_RESULT" VARCHAR2(16 CHAR) COLLATE "USING_NLS_COMP", 
	"OPT_RESULT_DESC" VARCHAR2(512 CHAR) COLLATE "USING_NLS_COMP", 
	"FAULT_SLIP_SEQ" VARCHAR2(64 CHAR) COLLATE "USING_NLS_COMP", 
	"ERROR_CODE" VARCHAR2(16 CHAR) COLLATE "USING_NLS_COMP", 
	"ERROR_MESSAGE" VARCHAR2(512 CHAR) COLLATE "USING_NLS_COMP", 
	"TRANS_AMOUNT" NUMBER(12,0), 
	"AFTER_AMOUNT" NUMBER(12,0), 
	"REPORT_TMS" VARCHAR2(14 CHAR) COLLATE "USING_NLS_COMP", 
	"RECEIVE_TMS" TIMESTAMP (6) DEFAULT SYSTIMESTAMP NOT NULL ENABLE, 
	"PROCESSED" VARCHAR2(1 CHAR) COLLATE "USING_NLS_COMP" DEFAULT '0' NOT NULL ENABLE, 
	"RAW_BODY" CLOB COLLATE "USING_NLS_COMP", 
	"CREATE_TMS" TIMESTAMP (6) DEFAULT SYSTIMESTAMP NOT NULL ENABLE, 
	 CONSTRAINT "CK_F2F_REPORT_TYPE" CHECK (REPORT_TYPE IN (
        'TAKE_TICKET_OK', 'TAKE_TICKET_FAIL', 'TOPUP_OK', 'TOPUP_FAIL', 'BOM_BIZ_RESULT')) ENABLE, 
	 CONSTRAINT "CK_F2F_REPORT_TOPUP" CHECK (TOPUP_STATUS IS NULL OR TOPUP_STATUS IN ('00', '01', '02', '03')) ENABLE, 
	 CONSTRAINT "PK_F2F_RESULT_REPORT" PRIMARY KEY ("ID")
  USING INDEX PCTFREE 10 INITRANS 2 MAXTRANS 255 COMPUTE STATISTICS 
  STORAGE(INITIAL 65536 NEXT 1048576 MINEXTENTS 1 MAXEXTENTS 2147483645
  PCTINCREASE 0 FREELISTS 1 FREELIST GROUPS 1
  BUFFER_POOL DEFAULT FLASH_CACHE DEFAULT CELL_FLASH_CACHE DEFAULT)
  TABLESPACE "USERS"  ENABLE
   )  DEFAULT COLLATION "USING_NLS_COMP" PCTFREE 10 PCTUSED 40 INITRANS 1 MAXTRANS 255 
  STORAGE(
  BUFFER_POOL DEFAULT FLASH_CACHE DEFAULT CELL_FLASH_CACHE DEFAULT)
  TABLESPACE "USERS" 
 LOB ("RAW_BODY") STORE AS SECUREFILE (
  ENABLE STORAGE IN ROW CHUNK 8192
  NOCACHE LOGGING  NOCOMPRESS  KEEP_DUPLICATES 
  STORAGE(
  BUFFER_POOL DEFAULT FLASH_CACHE DEFAULT CELL_FLASH_CACHE DEFAULT)) 
  PARTITION BY RANGE ("CREATE_TMS") INTERVAL (NUMTOYMINTERVAL(1, 'MONTH')) 
 (PARTITION "P_F2F_REPORT_INIT"  VALUES LESS THAN (TIMESTAMP' 2026-10-01 00:00:00') SEGMENT CREATION IMMEDIATE 
  PCTFREE 10 PCTUSED 40 INITRANS 1 MAXTRANS 255 
 NOCOMPRESS LOGGING 
  STORAGE(INITIAL 8388608 NEXT 1048576 MINEXTENTS 1 MAXEXTENTS 2147483645
  PCTINCREASE 0 FREELISTS 1 FREELIST GROUPS 1
  BUFFER_POOL DEFAULT FLASH_CACHE DEFAULT CELL_FLASH_CACHE DEFAULT)
  TABLESPACE "USERS" 
 LOB ("RAW_BODY") STORE AS SECUREFILE (
  TABLESPACE "USERS" ENABLE STORAGE IN ROW CHUNK 8192
  NOCACHE LOGGING  NOCOMPRESS  KEEP_DUPLICATES 
  STORAGE(INITIAL 8388608 NEXT 1048576 MINEXTENTS 1 MAXEXTENTS 2147483645
  PCTINCREASE 0
  BUFFER_POOL DEFAULT FLASH_CACHE DEFAULT CELL_FLASH_CACHE DEFAULT)) ) ;

COMMENT ON COLUMN "QDITP"."F2F_RESULT_REPORT"."ORDER_NO" IS '一般为ITP订单号；ERROR_CODE=2101时规格要求填取票二维码的randomFact，故不建外键';
   COMMENT ON COLUMN "QDITP"."F2F_RESULT_REPORT"."TOPUP_STATUS" IS '充值状态：00成功，01失败，02存疑，03取消';
   COMMENT ON COLUMN "QDITP"."F2F_RESULT_REPORT"."ERROR_CODE" IS '2101表示取票二维码超时需解锁订单';
   COMMENT ON COLUMN "QDITP"."F2F_RESULT_REPORT"."REPORT_TMS" IS '设备侧发生时间YYYYMMDDHHMMSS；ERROR_CODE=2101时为二维码生成时间';
   COMMENT ON COLUMN "QDITP"."F2F_RESULT_REPORT"."PROCESSED" IS '0未处理，1已处理；后续动作（退款、状态推进）由扫表驱动，与接收解耦';
   COMMENT ON COLUMN "QDITP"."F2F_RESULT_REPORT"."RAW_BODY" IS '原始报文留证，规格允许出现接口未声明的字段';
   COMMENT ON TABLE "QDITP"."F2F_RESULT_REPORT"  IS '设备业务结果上报，统一承载IF2A-04/05/06/07与BOM业务操作结果通知；规格要求断网重传，靠UK_F2F_REPORT_IDEM保证幂等。六个上报接口收敂为五个REPORT_TYPE：TVM的topupCardResultNoti与BOM的notiTopupResult同映射TOPUP_OK，前提是同一订单只会被单一渠道上报，因此唯一索引不含CHANNEL；若该前提被推翻，MUST改为(CHANNEL,REPORT_TYPE,ORDER_NO)';


-- QDITP.F2F_TICKET definition

CREATE TABLE "QDITP"."F2F_TICKET" 
   (	"ID" NUMBER(22,0) GENERATED BY DEFAULT AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE, 
	"ORDER_NO" VARCHAR2(64 CHAR) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"TICKET_LOGIC_NUM" VARCHAR2(64 CHAR) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"TRANS_DATE" VARCHAR2(14 CHAR) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"TICKET_PRICE" NUMBER(12,0) NOT NULL ENABLE, 
	"TICKET_STATUS" VARCHAR2(16 CHAR) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"ENTRY_STATION_CODE" VARCHAR2(16 CHAR) COLLATE "USING_NLS_COMP", 
	"EXIT_STATION_CODE" VARCHAR2(16 CHAR) COLLATE "USING_NLS_COMP", 
	"PAY_CHANNEL_CODE" VARCHAR2(8 CHAR) COLLATE "USING_NLS_COMP", 
	"REFUND_NO" VARCHAR2(64 CHAR) COLLATE "USING_NLS_COMP", 
	"CREATE_TMS" TIMESTAMP (6) DEFAULT SYSTIMESTAMP NOT NULL ENABLE, 
	"UPDATE_TMS" TIMESTAMP (6) DEFAULT SYSTIMESTAMP NOT NULL ENABLE, 
	 CONSTRAINT "CK_F2F_TICKET_STATUS" CHECK (TICKET_STATUS IN ('ISSUED', 'FAULT', 'REFUNDING', 'REFUNDED')) ENABLE, 
	 CONSTRAINT "PK_F2F_TICKET" PRIMARY KEY ("ID")
  USING INDEX PCTFREE 10 INITRANS 2 MAXTRANS 255 COMPUTE STATISTICS 
  STORAGE(INITIAL 65536 NEXT 1048576 MINEXTENTS 1 MAXEXTENTS 2147483645
  PCTINCREASE 0 FREELISTS 1 FREELIST GROUPS 1
  BUFFER_POOL DEFAULT FLASH_CACHE DEFAULT CELL_FLASH_CACHE DEFAULT)
  TABLESPACE "USERS"  ENABLE
   )  DEFAULT COLLATION "USING_NLS_COMP" SEGMENT CREATION IMMEDIATE 
  PCTFREE 10 PCTUSED 40 INITRANS 1 MAXTRANS 255 
 NOCOMPRESS LOGGING
  STORAGE(INITIAL 65536 NEXT 1048576 MINEXTENTS 1 MAXEXTENTS 2147483645
  PCTINCREASE 0 FREELISTS 1 FREELIST GROUPS 1
  BUFFER_POOL DEFAULT FLASH_CACHE DEFAULT CELL_FLASH_CACHE DEFAULT)
  TABLESPACE "USERS" ;

COMMENT ON COLUMN "QDITP"."F2F_TICKET"."TICKET_LOGIC_NUM" IS '票卡逻辑号，下单时未知，出票上报才有';
   COMMENT ON COLUMN "QDITP"."F2F_TICKET"."TRANS_DATE" IS '交易日期YYYYMMDDHHMMSS，BOM退款按逻辑号加此字段定位';
   COMMENT ON COLUMN "QDITP"."F2F_TICKET"."REFUND_NO" IS '已退款时回填退款单号';
   COMMENT ON TABLE "QDITP"."F2F_TICKET"  IS '单程票明细，出票结果上报时写入；退款按票粒度';


