-- QDITP.GATE_RETRY_QUEUE definition

CREATE TABLE "QDITP"."GATE_RETRY_QUEUE" 
   (	"ID" NUMBER(20,0) NOT NULL ENABLE, 
	"ORDER_NO" VARCHAR2(64 CHAR) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"TXN_DATE" VARCHAR2(8 CHAR) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"THIRD_USER_ID" VARCHAR2(64 CHAR) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"CARD_ID" VARCHAR2(32 CHAR) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"STATUS" VARCHAR2(16 CHAR) COLLATE "USING_NLS_COMP" DEFAULT 'PENDING' NOT NULL ENABLE, 
	"RETRY_COUNT" NUMBER(4,0) DEFAULT 0 NOT NULL ENABLE, 
	"MAX_RETRIES" NUMBER(4,0) DEFAULT 3 NOT NULL ENABLE, 
	"ERROR_MSG" VARCHAR2(512 CHAR) COLLATE "USING_NLS_COMP", 
	"CREATE_TIME" TIMESTAMP (6) DEFAULT SYSTIMESTAMP NOT NULL ENABLE, 
	"UPDATE_TIME" TIMESTAMP (6) DEFAULT SYSTIMESTAMP NOT NULL ENABLE, 
	"CONSUME_TIME" TIMESTAMP (6), 
	"FINISH_TIME" TIMESTAMP (6), 
	 CONSTRAINT "PK_GATE_RETRY_QUEUE" PRIMARY KEY ("ID")
  USING INDEX PCTFREE 10 INITRANS 2 MAXTRANS 255 COMPUTE STATISTICS 
  TABLESPACE "USERS"  ENABLE
   )  DEFAULT COLLATION "USING_NLS_COMP" SEGMENT CREATION DEFERRED 
  PCTFREE 10 PCTUSED 40 INITRANS 1 MAXTRANS 255 
 NOCOMPRESS LOGGING
  TABLESPACE "USERS" ;

COMMENT ON COLUMN "QDITP"."GATE_RETRY_QUEUE"."ID" IS '主键';
   COMMENT ON COLUMN "QDITP"."GATE_RETRY_QUEUE"."STATUS" IS '队列状态：PENDING=待消费, PROCESSING=消费中, DONE=已完成, FAILED=失败';
   COMMENT ON TABLE "QDITP"."GATE_RETRY_QUEUE"  IS '用户主动重试扣费队列表（ADR-D169）';


