ALTER TABLE "QDITP"."GATE_TXN_PAY" ADD CONSTRAINT "UK_GATE_TXN_PAY_BIZ_KEY" UNIQUE ("CARD_ID", "TRX_TYPE", "OUT_TIME", "TICKET_TRANS_SEQ", "DEVICE_ID", "TXN_DATE")
  USING INDEX "QDITP"."UK_GATE_TXN_PAY_BIZ"  ENABLE;

COMMENT ON COLUMN "QDITP"."GATE_TXN_PAY"."ID" IS '主键ID';
   COMMENT ON COLUMN "QDITP"."GATE_TXN_PAY"."ORDER_NO" IS '地铁侧扣费订单号，同时作为支付接口orderNo';
   COMMENT ON COLUMN "QDITP"."GATE_TXN_PAY"."DEBIT_STATUS" IS '扣费状态：INIT初始化，PROCESSING处理中，SUCCESS成功，FAIL失败，RETRY待补扣，CLOSED关闭';
   COMMENT ON COLUMN "QDITP"."GATE_TXN_PAY"."THIRD_USER_ID" IS '第三方用户ID，对应设备报文itpUserId转换后的用户标识';
   COMMENT ON COLUMN "QDITP"."GATE_TXN_PAY"."CARD_ID" IS '逻辑卡号';
   COMMENT ON COLUMN "QDITP"."GATE_TXN_PAY"."CARD_TYPE" IS '票卡类型';
   COMMENT ON COLUMN "QDITP"."GATE_TXN_PAY"."DEVICE_ID" IS '设备ID，公共请求参数';
   COMMENT ON COLUMN "QDITP"."GATE_TXN_PAY"."TRX_TYPE" IS '交易类型：02出站，03超时出站';
   COMMENT ON COLUMN "QDITP"."GATE_TXN_PAY"."TICKET_TRANS_SEQ" IS '二维码交易计数器，文档字段名为tikcetTransSeq';
   COMMENT ON COLUMN "QDITP"."GATE_TXN_PAY"."IN_STATION" IS '进站车站代码';
   COMMENT ON COLUMN "QDITP"."GATE_TXN_PAY"."IN_TIME" IS '进站时间，格式YYYYMMDDHH24MISS';
   COMMENT ON COLUMN "QDITP"."GATE_TXN_PAY"."OUT_STATION" IS '出站车站代码';
   COMMENT ON COLUMN "QDITP"."GATE_TXN_PAY"."OUT_TIME" IS '出站时间，格式YYYYMMDDHH24MISS';
   COMMENT ON COLUMN "QDITP"."GATE_TXN_PAY"."TXN_DATE" IS '出站交易日期，取OUT_TIME前8位，格式YYYYMMDD，用于月分区';
   COMMENT ON COLUMN "QDITP"."GATE_TXN_PAY"."TRX_AMOUNT" IS '闸机交易金额，单位分';
   COMMENT ON COLUMN "QDITP"."GATE_TXN_PAY"."OVERTIME_AMOUNT" IS '超时金额，单位分';
   COMMENT ON COLUMN "QDITP"."GATE_TXN_PAY"."TOTAL_AMOUNT" IS '应扣总金额，单位分';
   COMMENT ON COLUMN "QDITP"."GATE_TXN_PAY"."ISSUE_CHANNEL_CODE" IS '发行渠道代码';
   COMMENT ON COLUMN "QDITP"."GATE_TXN_PAY"."SIGN_CHANNEL_CODE" IS '签约通道代码';
   COMMENT ON COLUMN "QDITP"."GATE_TXN_PAY"."REMARK" IS '备注';
   COMMENT ON COLUMN "QDITP"."GATE_TXN_PAY"."CREATE_TIME" IS '创建时间';
   COMMENT ON COLUMN "QDITP"."GATE_TXN_PAY"."UPDATE_TIME" IS '更新时间';
   COMMENT ON COLUMN "QDITP"."GATE_TXN_PAY"."TICKET_STATUS" IS '票卡状态：01无交易,02进站,03进站超时,04进站失败,05出站,06出站超时,70异常,80自助补出站';
   COMMENT ON COLUMN "QDITP"."GATE_TXN_PAY"."ORDER_EXP_TYPE" IS '订单异常类型：0正常,1单边账(入),2单边账(出),3单边入站人工,4单边出站人工,5双段计费超时';
   COMMENT ON COLUMN "QDITP"."GATE_TXN_PAY"."OFFLINE_FLAG" IS '离线码标识：Y/N';
   COMMENT ON COLUMN "QDITP"."GATE_TXN_PAY"."ENTRY_STATION_NAME" IS '进站车站名称';
   COMMENT ON COLUMN "QDITP"."GATE_TXN_PAY"."EXIT_STATION_NAME" IS '出站车站名称';
   COMMENT ON COLUMN "QDITP"."GATE_TXN_PAY"."COMPANION_FLAG" IS '同行票标识：Y/N';
   COMMENT ON COLUMN "QDITP"."GATE_TXN_PAY"."TICKET_CODE" IS '日票票号';
   COMMENT ON COLUMN "QDITP"."GATE_TXN_PAY"."COUNTING_TIMES" IS '计次票剩余可用次数';
   COMMENT ON COLUMN "QDITP"."GATE_TXN_PAY"."COUNTING_FLAG" IS '计次/计时标识：1=计时,2=计次';
   COMMENT ON COLUMN "QDITP"."GATE_TXN_PAY"."ATTRIBUTABLE_PARTY" IS '订单应收商户';
   COMMENT ON COLUMN "QDITP"."GATE_TXN_PAY"."RECEIVING_PARTY" IS '订单实收商户';
   COMMENT ON COLUMN "QDITP"."GATE_TXN_PAY"."PAYMENT_VENDOR" IS '支付厂商编码，钱包为0B';
   COMMENT ON COLUMN "QDITP"."GATE_TXN_PAY"."CHANNEL_TYPE" IS '交易渠道类型，01为蓝牙';
   COMMENT ON COLUMN "QDITP"."GATE_TXN_PAY"."PAY_USER_ID" IS '钱包支付用户标识';
   COMMENT ON COLUMN "QDITP"."GATE_TXN_PAY"."TRANSFER_FLAG" IS '钱包换乘标识：01无换乘，02有换乘';
   COMMENT ON COLUMN "QDITP"."GATE_TXN_PAY"."CUMULATIVE_TYPE" IS '钱包累计类型：01正常出站，02超时出站，03不累计';
   COMMENT ON COLUMN "QDITP"."GATE_TXN_PAY"."ORIGINAL_FARE" IS '地铁进出站原价，单位分';
   COMMENT ON COLUMN "QDITP"."GATE_TXN_PAY"."WALLET_TOTAL_AMT" IS '钱包查询到的累计金额，单位分';
   COMMENT ON COLUMN "QDITP"."GATE_TXN_PAY"."DISCOUNT_LEVEL_AMT" IS '命中的折扣金额门槛，单位分';
   COMMENT ON COLUMN "QDITP"."GATE_TXN_PAY"."DISCOUNT_RATE" IS '命中的折扣率';
   COMMENT ON COLUMN "QDITP"."GATE_TXN_PAY"."EXPECTED_GATE_AMOUNT" IS '公式计算的期望闸机金额，单位分';
   COMMENT ON COLUMN "QDITP"."GATE_TXN_PAY"."DISCOUNT_CALC_STATUS" IS 'SUCCESS/FALLBACK/SKIPPED/OFFLINE_FARE_PENDING';
   COMMENT ON COLUMN "QDITP"."GATE_TXN_PAY"."DISCOUNT_CALC_MSG" IS '优惠计算说明或降级原因';
   COMMENT ON COLUMN "QDITP"."GATE_TXN_PAY"."INDUSTRY_DETAIL" IS '支付宝出行行业明细JSON，21键，出站落单时由fep-dev-server组装后整块透传，仅ISSUE_CHANNEL_CODE=07有值';
   COMMENT ON COLUMN "QDITP"."GATE_TXN_PAY"."DEBIT_RETRY_TIMES" IS '批量重试已发起次数，达到 gate.debitRetry.maxTimes 后不再被扫表谓词命中；人工排查用 DEBIT_RETRY_TIMES >= 上限 过滤';
   COMMENT ON COLUMN "QDITP"."GATE_TXN_PAY"."DEBIT_NEXT_RETRY_TIME" IS '下次允许批量重试的时刻，NULL 表示立即可重试；每次发起后置为 SYSTIMESTAMP + gate.debitRetry.backoffMinutes，防止同日多次触发把同一笔连扣两遍';
   COMMENT ON COLUMN "QDITP"."GATE_TXN_PAY"."DEBIT_FAIL_CODE" IS '批量重试落点语义码：BIZ_REJECTED 支付中心业务拒绝（重试无意义、等人工），UNREACHABLE 未获答复（下轮继续）；明细原因看 REMARK';
   COMMENT ON COLUMN "QDITP"."GATE_TXN_PAY"."DEBIT_FAIL_MSG" IS '批量重试记账说明，含第几次重试与落点状态；NEVER 拿它当扫表谓词';
   COMMENT ON COLUMN "QDITP"."GATE_TXN_PAY"."ADVICE_OPT" IS 'BOM补站操作类型：空=真实闸机检票或APP自助补站,005=免费更新,006=付费更新,018=补进站,020=免费更新(无时间窗)；非空即BOM补站单，现场已收款，NEVER由ITP发起扣款';
   COMMENT ON TABLE "QDITP"."GATE_TXN_PAY"  IS '二维码过闸扣费订单表';


-- QDITP.GEN_TABLE definition

CREATE TABLE "QDITP"."GEN_TABLE" 
   (	"TABLE_ID" NUMBER(19,0) GENERATED BY DEFAULT ON NULL AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE, 
	"TABLE_NAME" VARCHAR2(200 CHAR) COLLATE "USING_NLS_COMP", 
	"TABLE_COMMENT" VARCHAR2(500 CHAR) COLLATE "USING_NLS_COMP", 
	"SUB_TABLE_NAME" VARCHAR2(64 CHAR) COLLATE "USING_NLS_COMP", 
	"SUB_TABLE_FK_NAME" VARCHAR2(64 CHAR) COLLATE "USING_NLS_COMP", 
	"CLASS_NAME" VARCHAR2(100 CHAR) COLLATE "USING_NLS_COMP", 
	"TPL_CATEGORY" VARCHAR2(200 CHAR) COLLATE "USING_NLS_COMP" DEFAULT 'crud', 
	"TPL_WEB_TYPE" VARCHAR2(30 CHAR) COLLATE "USING_NLS_COMP", 
	"PACKAGE_NAME" VARCHAR2(100 CHAR) COLLATE "USING_NLS_COMP", 
	"MODULE_NAME" VARCHAR2(30 CHAR) COLLATE "USING_NLS_COMP", 
	"BUSINESS_NAME" VARCHAR2(30 CHAR) COLLATE "USING_NLS_COMP", 
	"FUNCTION_NAME" VARCHAR2(50 CHAR) COLLATE "USING_NLS_COMP", 
	"FUNCTION_AUTHOR" VARCHAR2(50 CHAR) COLLATE "USING_NLS_COMP", 
	"GEN_TYPE" CHAR(1 CHAR) COLLATE "USING_NLS_COMP" DEFAULT '0', 
	"GEN_PATH" VARCHAR2(200 CHAR) COLLATE "USING_NLS_COMP" DEFAULT '/', 
	"OPTIONS" VARCHAR2(1000 CHAR) COLLATE "USING_NLS_COMP", 
	"CREATE_BY" VARCHAR2(64 CHAR) COLLATE "USING_NLS_COMP", 
	"CREATE_TIME" DATE, 
	"UPDATE_BY" VARCHAR2(64 CHAR) COLLATE "USING_NLS_COMP", 
	"UPDATE_TIME" DATE, 
	"REMARK" VARCHAR2(500 CHAR) COLLATE "USING_NLS_COMP", 
	 PRIMARY KEY ("TABLE_ID")
  USING INDEX PCTFREE 10 INITRANS 2 MAXTRANS 255 COMPUTE STATISTICS 
  TABLESPACE "USERS"  ENABLE
   )  DEFAULT COLLATION "USING_NLS_COMP" SEGMENT CREATION DEFERRED 
  PCTFREE 10 PCTUSED 40 INITRANS 1 MAXTRANS 255 
 NOCOMPRESS LOGGING
  TABLESPACE "USERS" ;

COMMENT ON COLUMN "QDITP"."GEN_TABLE"."TABLE_ID" IS '编号';
   COMMENT ON COLUMN "QDITP"."GEN_TABLE"."TABLE_NAME" IS '表名称';
   COMMENT ON COLUMN "QDITP"."GEN_TABLE"."TABLE_COMMENT" IS '表描述';
   COMMENT ON COLUMN "QDITP"."GEN_TABLE"."SUB_TABLE_NAME" IS '关联子表的表名';
   COMMENT ON COLUMN "QDITP"."GEN_TABLE"."SUB_TABLE_FK_NAME" IS '子表关联的外键名';
   COMMENT ON COLUMN "QDITP"."GEN_TABLE"."CLASS_NAME" IS '实体类名称';
   COMMENT ON COLUMN "QDITP"."GEN_TABLE"."TPL_CATEGORY" IS '使用的模板（crud单表操作 tree树表操作）';
   COMMENT ON COLUMN "QDITP"."GEN_TABLE"."TPL_WEB_TYPE" IS '前端模板类型（element-ui模版 element-plus模版）';
   COMMENT ON COLUMN "QDITP"."GEN_TABLE"."PACKAGE_NAME" IS '生成包路径';
   COMMENT ON COLUMN "QDITP"."GEN_TABLE"."MODULE_NAME" IS '生成模块名';
   COMMENT ON COLUMN "QDITP"."GEN_TABLE"."BUSINESS_NAME" IS '生成业务名';
   COMMENT ON COLUMN "QDITP"."GEN_TABLE"."FUNCTION_NAME" IS '生成功能名';
   COMMENT ON COLUMN "QDITP"."GEN_TABLE"."FUNCTION_AUTHOR" IS '生成功能作者';
   COMMENT ON COLUMN "QDITP"."GEN_TABLE"."GEN_TYPE" IS '生成代码方式（0zip压缩包 1自定义路径）';
   COMMENT ON COLUMN "QDITP"."GEN_TABLE"."GEN_PATH" IS '生成路径（不填默认项目路径）';
   COMMENT ON COLUMN "QDITP"."GEN_TABLE"."OPTIONS" IS '其它生成选项';
   COMMENT ON COLUMN "QDITP"."GEN_TABLE"."CREATE_BY" IS '创建者';
   COMMENT ON COLUMN "QDITP"."GEN_TABLE"."CREATE_TIME" IS '创建时间';
   COMMENT ON COLUMN "QDITP"."GEN_TABLE"."UPDATE_BY" IS '更新者';
   COMMENT ON COLUMN "QDITP"."GEN_TABLE"."UPDATE_TIME" IS '更新时间';
   COMMENT ON COLUMN "QDITP"."GEN_TABLE"."REMARK" IS '备注';
   COMMENT ON TABLE "QDITP"."GEN_TABLE"  IS '代码生成业务表';


-- QDITP.GEN_TABLE_COLUMN definition

CREATE TABLE "QDITP"."GEN_TABLE_COLUMN" 
   (	"COLUMN_ID" NUMBER(19,0) GENERATED BY DEFAULT ON NULL AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE, 
	"TABLE_ID" NUMBER(19,0), 
	"COLUMN_NAME" VARCHAR2(200 CHAR) COLLATE "USING_NLS_COMP", 
	"COLUMN_COMMENT" VARCHAR2(500 CHAR) COLLATE "USING_NLS_COMP", 
	"COLUMN_TYPE" VARCHAR2(100 CHAR) COLLATE "USING_NLS_COMP", 
	"JAVA_TYPE" VARCHAR2(500 CHAR) COLLATE "USING_NLS_COMP", 
	"JAVA_FIELD" VARCHAR2(200 CHAR) COLLATE "USING_NLS_COMP", 
	"IS_PK" CHAR(1 CHAR) COLLATE "USING_NLS_COMP", 
	"IS_INCREMENT" CHAR(1 CHAR) COLLATE "USING_NLS_COMP", 
	"IS_REQUIRED" CHAR(1 CHAR) COLLATE "USING_NLS_COMP", 
	"IS_INSERT" CHAR(1 CHAR) COLLATE "USING_NLS_COMP", 
	"IS_EDIT" CHAR(1 CHAR) COLLATE "USING_NLS_COMP", 
	"IS_LIST" CHAR(1 CHAR) COLLATE "USING_NLS_COMP", 
	"IS_QUERY" CHAR(1 CHAR) COLLATE "USING_NLS_COMP", 
	"QUERY_TYPE" VARCHAR2(200 CHAR) COLLATE "USING_NLS_COMP" DEFAULT 'EQ', 
	"HTML_TYPE" VARCHAR2(200 CHAR) COLLATE "USING_NLS_COMP", 
	"DICT_TYPE" VARCHAR2(200 CHAR) COLLATE "USING_NLS_COMP", 
	"SORT" NUMBER(10,0), 
	"CREATE_BY" VARCHAR2(64 CHAR) COLLATE "USING_NLS_COMP", 
	"CREATE_TIME" DATE, 
	"UPDATE_BY" VARCHAR2(64 CHAR) COLLATE "USING_NLS_COMP", 
	"UPDATE_TIME" DATE, 
	 PRIMARY KEY ("COLUMN_ID")
  USING INDEX PCTFREE 10 INITRANS 2 MAXTRANS 255 COMPUTE STATISTICS 
  TABLESPACE "USERS"  ENABLE
   )  DEFAULT COLLATION "USING_NLS_COMP" SEGMENT CREATION DEFERRED 
  PCTFREE 10 PCTUSED 40 INITRANS 1 MAXTRANS 255 
 NOCOMPRESS LOGGING
  TABLESPACE "USERS" ;

COMMENT ON COLUMN "QDITP"."GEN_TABLE_COLUMN"."COLUMN_ID" IS '编号';
   COMMENT ON COLUMN "QDITP"."GEN_TABLE_COLUMN"."TABLE_ID" IS '归属表编号';
   COMMENT ON COLUMN "QDITP"."GEN_TABLE_COLUMN"."COLUMN_NAME" IS '列名称';
   COMMENT ON COLUMN "QDITP"."GEN_TABLE_COLUMN"."COLUMN_COMMENT" IS '列描述';
   COMMENT ON COLUMN "QDITP"."GEN_TABLE_COLUMN"."COLUMN_TYPE" IS '列类型';
   COMMENT ON COLUMN "QDITP"."GEN_TABLE_COLUMN"."JAVA_TYPE" IS 'JAVA类型';
   COMMENT ON COLUMN "QDITP"."GEN_TABLE_COLUMN"."JAVA_FIELD" IS 'JAVA字段名';
   COMMENT ON COLUMN "QDITP"."GEN_TABLE_COLUMN"."IS_PK" IS '是否主键（1是）';
   COMMENT ON COLUMN "QDITP"."GEN_TABLE_COLUMN"."IS_INCREMENT" IS '是否自增（1是）';
   COMMENT ON COLUMN "QDITP"."GEN_TABLE_COLUMN"."IS_REQUIRED" IS '是否必填（1是）';
   COMMENT ON COLUMN "QDITP"."GEN_TABLE_COLUMN"."IS_INSERT" IS '是否为插入字段（1是）';
   COMMENT ON COLUMN "QDITP"."GEN_TABLE_COLUMN"."IS_EDIT" IS '是否编辑字段（1是）';
   COMMENT ON COLUMN "QDITP"."GEN_TABLE_COLUMN"."IS_LIST" IS '是否列表字段（1是）';
   COMMENT ON COLUMN "QDITP"."GEN_TABLE_COLUMN"."IS_QUERY" IS '是否查询字段（1是）';
   COMMENT ON COLUMN "QDITP"."GEN_TABLE_COLUMN"."QUERY_TYPE" IS '查询方式（等于、不等于、大于、小于、范围）';
   COMMENT ON COLUMN "QDITP"."GEN_TABLE_COLUMN"."HTML_TYPE" IS '显示类型（文本框、文本域、下拉框、复选框、单选框、日期控件）';
   COMMENT ON COLUMN "QDITP"."GEN_TABLE_COLUMN"."DICT_TYPE" IS '字典类型';
   COMMENT ON COLUMN "QDITP"."GEN_TABLE_COLUMN"."SORT" IS '排序';
   COMMENT ON COLUMN "QDITP"."GEN_TABLE_COLUMN"."CREATE_BY" IS '创建者';
   COMMENT ON COLUMN "QDITP"."GEN_TABLE_COLUMN"."CREATE_TIME" IS '创建时间';
   COMMENT ON COLUMN "QDITP"."GEN_TABLE_COLUMN"."UPDATE_BY" IS '更新者';
   COMMENT ON COLUMN "QDITP"."GEN_TABLE_COLUMN"."UPDATE_TIME" IS '更新时间';
   COMMENT ON TABLE "QDITP"."GEN_TABLE_COLUMN"  IS '代码生成业务表字段';


-- QDITP.LOGIC_CARD_POOL_BATCH definition

CREATE TABLE "QDITP"."LOGIC_CARD_POOL_BATCH" 
   (	"BATCH_NO" NUMBER(6,0) NOT NULL ENABLE, 
	"REQUEST_SEQ" VARCHAR2(6 CHAR) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"CARD_TYPE" VARCHAR2(4 CHAR) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"ACC_TICKET_TYPE" VARCHAR2(2 CHAR) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"REQUEST_NUM" NUMBER(6,0) NOT NULL ENABLE, 
	"SOURCE" VARCHAR2(16 CHAR) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"FILE_NAME" VARCHAR2(255 CHAR) COLLATE "USING_NLS_COMP", 
	"FTP_PATH" VARCHAR2(512 CHAR) COLLATE "USING_NLS_COMP", 
	"FILE_SIZE" NUMBER(19,0), 
	"FILE_SHA256" VARCHAR2(64 CHAR) COLLATE "USING_NLS_COMP", 
	"TOTAL_COUNT" NUMBER(10,0) DEFAULT 0 NOT NULL ENABLE, 
	"VALID_COUNT" NUMBER(10,0) DEFAULT 0 NOT NULL ENABLE, 
	"DUPLICATE_COUNT" NUMBER(10,0) DEFAULT 0 NOT NULL ENABLE, 
	"INVALID_COUNT" NUMBER(10,0) DEFAULT 0 NOT NULL ENABLE, 
	"STATUS" VARCHAR2(16 CHAR) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"ERROR_MSG" VARCHAR2(2000 CHAR) COLLATE "USING_NLS_COMP", 
	"RETRY_COUNT" NUMBER(5,0) DEFAULT 0 NOT NULL ENABLE, 
	"OPERATOR" VARCHAR2(64 CHAR) COLLATE "USING_NLS_COMP", 
	"CREATE_TIME" TIMESTAMP (6) DEFAULT SYSTIMESTAMP NOT NULL ENABLE, 
	"FINISH_TIME" TIMESTAMP (6), 
	 CONSTRAINT "PK_LOGIC_CARD_POOL_BATCH" PRIMARY KEY ("BATCH_NO")
  USING INDEX PCTFREE 10 INITRANS 2 MAXTRANS 255 COMPUTE STATISTICS 
  STORAGE(INITIAL 65536 NEXT 1048576 MINEXTENTS 1 MAXEXTENTS 2147483645
  PCTINCREASE 0 FREELISTS 1 FREELIST GROUPS 1
  BUFFER_POOL DEFAULT FLASH_CACHE DEFAULT CELL_FLASH_CACHE DEFAULT)
  TABLESPACE "USERS"  ENABLE, 
	 CONSTRAINT "UK_LOGIC_CARD_POOL_BATCH_SEQ" UNIQUE ("REQUEST_SEQ")
  USING INDEX PCTFREE 10 INITRANS 2 MAXTRANS 255 COMPUTE STATISTICS 
  STORAGE(INITIAL 65536 NEXT 1048576 MINEXTENTS 1 MAXEXTENTS 2147483645
  PCTINCREASE 0 FREELISTS 1 FREELIST GROUPS 1
  BUFFER_POOL DEFAULT FLASH_CACHE DEFAULT CELL_FLASH_CACHE DEFAULT)
  TABLESPACE "USERS"  ENABLE
   )  DEFAULT COLLATION "USING_NLS_COMP" SEGMENT CREATION IMMEDIATE 
  PCTFREE 10 PCTUSED 40 INITRANS 1 MAXTRANS 255 
 NOCOMPRESS LOGGING
  STORAGE(INITIAL 65536 NEXT 1048576 MINEXTENTS 1 MAXEXTENTS 2147483645
  PCTINCREASE 0 FREELISTS 1 FREELIST GROUPS 1
  BUFFER_POOL DEFAULT FLASH_CACHE DEFAULT CELL_FLASH_CACHE DEFAULT)
  TABLESPACE "USERS" ;

COMMENT ON TABLE "QDITP"."LOGIC_CARD_POOL_BATCH"  IS '逻辑卡号批次及ACC文件导入记录';


-- QDITP.LOGIC_CARD_POOL_TYPE_LOCK definition

CREATE TABLE "QDITP"."LOGIC_CARD_POOL_TYPE_LOCK" 
   (	"CARD_TYPE" VARCHAR2(4 CHAR) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"LOCK_OWNER" VARCHAR2(36 CHAR) COLLATE "USING_NLS_COMP", 
	"LOCK_TIME" TIMESTAMP (6), 
