COMMENT ON TABLE "QDITP"."LOGIC_CARD_POOL_TYPE_LOCK"  IS '逻辑卡号池票种级批次锁';


-- QDITP.METRO_AGM_KEY_POOL definition

CREATE TABLE "QDITP"."METRO_AGM_KEY_POOL" 
   (	"ID" NUMBER(20,0) NOT NULL ENABLE, 
	"PROVIDER_ID" VARCHAR2(10) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"KEY_BATH_NUMBER" NUMBER NOT NULL ENABLE, 
	"KEY_IDX" VARCHAR2(10) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
