	"MANAGER_ID" VARCHAR2(20) COLLATE "USING_NLS_COMP", 
	"RESERVE" VARCHAR2(100) COLLATE "USING_NLS_COMP", 
	"REMARK" VARCHAR2(100) COLLATE "USING_NLS_COMP", 
	"KEY_TYPE" NUMBER, 
	"UPDATE_DATE" DATE, 
	"REG_DATE" DATE DEFAULT sysdate NOT NULL ENABLE, 
	 CONSTRAINT "PK_METRO_AGM_KEY_POOL" PRIMARY KEY ("ID")
  USING INDEX PCTFREE 10 INITRANS 2 MAXTRANS 255 COMPUTE STATISTICS 
