  PCTINCREASE 0 FREELISTS 1 FREELIST GROUPS 1
  BUFFER_POOL DEFAULT FLASH_CACHE DEFAULT CELL_FLASH_CACHE DEFAULT)
  TABLESPACE "USERS"  ENABLE, 
	 CONSTRAINT "UK_METRO_AGM_KEY_POOL" UNIQUE ("PROVIDER_ID", "KEY_BATH_NUMBER", "KEY_IDX")
  USING INDEX PCTFREE 10 INITRANS 2 MAXTRANS 255 COMPUTE STATISTICS 
  STORAGE(INITIAL 65536 NEXT 1048576 MINEXTENTS 1 MAXEXTENTS 2147483645
  PCTINCREASE 0 FREELISTS 1 FREELIST GROUPS 1
  BUFFER_POOL DEFAULT FLASH_CACHE DEFAULT CELL_FLASH_CACHE DEFAULT)
  TABLESPACE "USERS"  ENABLE
   )  DEFAULT COLLATION "USING_NLS_COMP" SEGMENT CREATION IMMEDIATE 
  PCTFREE 10 PCTUSED 40 INITRANS 1 MAXTRANS 255 
 NOCOMPRESS LOGGING
  STORAGE(INITIAL 65536 NEXT 1048576 MINEXTENTS 1 MAXEXTENTS 2147483645
  PCTINCREASE 0 FREELISTS 1 FREELIST GROUPS 1
  BUFFER_POOL DEFAULT FLASH_CACHE DEFAULT CELL_FLASH_CACHE DEFAULT)
  TABLESPACE "USERS" ;

COMMENT ON COLUMN "QDITP"."METRO_AGM_KEY_POOL"."KEY_IDX" IS '密钥索引';
   COMMENT ON COLUMN "QDITP"."METRO_AGM_KEY_POOL"."KEY_VALUE" IS '密钥值';
   COMMENT ON COLUMN "QDITP"."METRO_AGM_KEY_POOL"."KEY_TYPE" IS '0非对称密钥，1对称密钥';
   COMMENT ON TABLE "QDITP"."METRO_AGM_KEY_POOL"  IS 'AGM渠道密钥池';


-- QDITP.METRO_AGM_KEY_VERSION definition

CREATE TABLE "QDITP"."METRO_AGM_KEY_VERSION" 
   (	"ID" NUMBER(20,0) NOT NULL ENABLE, 
