	 CONSTRAINT "PK_METRO_AGM_KEY_VERSION" PRIMARY KEY ("ID")
  USING INDEX PCTFREE 10 INITRANS 2 MAXTRANS 255 COMPUTE STATISTICS 
  STORAGE(INITIAL 65536 NEXT 1048576 MINEXTENTS 1 MAXEXTENTS 2147483645
  PCTINCREASE 0 FREELISTS 1 FREELIST GROUPS 1
  BUFFER_POOL DEFAULT FLASH_CACHE DEFAULT CELL_FLASH_CACHE DEFAULT)
  TABLESPACE "USERS"  ENABLE, 
	 CONSTRAINT "UK_METRO_AGM_KEY_VERSION" UNIQUE ("PROVIDER_ID", "KEY_BATH_NUMBER")
  USING INDEX PCTFREE 10 INITRANS 2 MAXTRANS 255 COMPUTE STATISTICS 
  STORAGE(INITIAL 65536 NEXT 1048576 MINEXTENTS 1 MAXEXTENTS 2147483645
  PCTINCREASE 0 FREELISTS 1 FREELIST GROUPS 1
  BUFFER_POOL DEFAULT FLASH_CACHE DEFAULT CELL_FLASH_CACHE DEFAULT)
  TABLESPACE "USERS"  ENABLE
   )  DEFAULT COLLATION "USING_NLS_COMP" SEGMENT CREATION IMMEDIATE 
  PCTFREE 10 PCTUSED 40 INITRANS 1 MAXTRANS 255 
 NOCOMPRESS LOGGING
  STORAGE(INITIAL 65536 NEXT 1048576 MINEXTENTS 1 MAXEXTENTS 2147483645
  PCTINCREASE 0 FREELISTS 1 FREELIST GROUPS 1
  BUFFER_POOL DEFAULT FLASH_CACHE DEFAULT CELL_FLASH_CACHE DEFAULT)
  TABLESPACE "USERS" ;

COMMENT ON COLUMN "QDITP"."METRO_AGM_KEY_VERSION"."PROVIDER_ID" IS '渠道编码，例如01';
   COMMENT ON COLUMN "QDITP"."METRO_AGM_KEY_VERSION"."KEY_BATH_NUMBER" IS '密钥批次号';
   COMMENT ON COLUMN "QDITP"."METRO_AGM_KEY_VERSION"."PUBLIC_KEY_VERSION_STATUS" IS '20010初始化，20020审批通过，20030拒绝';
   COMMENT ON TABLE "QDITP"."METRO_AGM_KEY_VERSION"  IS 'AGM渠道密钥批次及审批状态';


-- QDITP.METRO_CA_KEYSTORE definition

CREATE TABLE "QDITP"."METRO_CA_KEYSTORE" 
   (	"ID" NUMBER(20,0) NOT NULL ENABLE, 
	"KEY_IDX" VARCHAR2(4) COLLATE "USING_NLS_COMP", 
