	"KEY_PUBLIC" VARCHAR2(256) COLLATE "USING_NLS_COMP", 
	"KEY_EFFECTIVE_DATE" VARCHAR2(20) COLLATE "USING_NLS_COMP", 
	"KEY_STATUS" NUMBER, 
	"MANAGER_ID" VARCHAR2(20) COLLATE "USING_NLS_COMP", 
	"RESERVE" VARCHAR2(100) COLLATE "USING_NLS_COMP", 
	"REMARK" VARCHAR2(100) COLLATE "USING_NLS_COMP", 
	"UPDATE_DATE" DATE, 
	"REG_DATE" DATE NOT NULL ENABLE, 
	"KEY_PAIR" VARCHAR2(1024) COLLATE "USING_NLS_COMP", 
	 CONSTRAINT "PK_METRO_CA_KEYSTORE" PRIMARY KEY ("ID")
  USING INDEX PCTFREE 10 INITRANS 2 MAXTRANS 255 COMPUTE STATISTICS 
  STORAGE(INITIAL 65536 NEXT 1048576 MINEXTENTS 1 MAXEXTENTS 2147483645
  PCTINCREASE 0 FREELISTS 1 FREELIST GROUPS 1
  BUFFER_POOL DEFAULT FLASH_CACHE DEFAULT CELL_FLASH_CACHE DEFAULT)
  TABLESPACE "USERS"  ENABLE
   )  DEFAULT COLLATION "USING_NLS_COMP" SEGMENT CREATION IMMEDIATE 
  PCTFREE 10 PCTUSED 40 INITRANS 1 MAXTRANS 255 
 NOCOMPRESS LOGGING
  STORAGE(INITIAL 65536 NEXT 1048576 MINEXTENTS 1 MAXEXTENTS 2147483645
  PCTINCREASE 0 FREELISTS 1 FREELIST GROUPS 1
  BUFFER_POOL DEFAULT FLASH_CACHE DEFAULT CELL_FLASH_CACHE DEFAULT)
  TABLESPACE "USERS" ;

COMMENT ON COLUMN "QDITP"."METRO_CA_KEYSTORE"."ID" IS '主键';
   COMMENT ON COLUMN "QDITP"."METRO_CA_KEYSTORE"."KEY_IDX" IS 'ITP密钥索引';
   COMMENT ON COLUMN "QDITP"."METRO_CA_KEYSTORE"."KEY_PRIVATE" IS 'ITP私钥';
   COMMENT ON COLUMN "QDITP"."METRO_CA_KEYSTORE"."KEY_PUBLIC" IS 'ITP公钥';
   COMMENT ON COLUMN "QDITP"."METRO_CA_KEYSTORE"."KEY_EFFECTIVE_DATE" IS '有效期';
   COMMENT ON COLUMN "QDITP"."METRO_CA_KEYSTORE"."KEY_STATUS" IS '状态：0初始化，1使用，2暂停';
   COMMENT ON COLUMN "QDITP"."METRO_CA_KEYSTORE"."MANAGER_ID" IS '管理员编码';
   COMMENT ON COLUMN "QDITP"."METRO_CA_KEYSTORE"."RESERVE" IS '预留字段';
   COMMENT ON COLUMN "QDITP"."METRO_CA_KEYSTORE"."REMARK" IS '备注';
   COMMENT ON COLUMN "QDITP"."METRO_CA_KEYSTORE"."UPDATE_DATE" IS '修改日期';
   COMMENT ON COLUMN "QDITP"."METRO_CA_KEYSTORE"."REG_DATE" IS '注册日期';
   COMMENT ON COLUMN "QDITP"."METRO_CA_KEYSTORE"."KEY_PAIR" IS 'SM2密钥对';
   COMMENT ON TABLE "QDITP"."METRO_CA_KEYSTORE"  IS '地铁会CA密钥仓库';


