-- QDITP.PAY_CALLBACK_LOG definition

CREATE TABLE "QDITP"."PAY_CALLBACK_LOG" 
   (	"ID" NUMBER(20,0) NOT NULL ENABLE, 
	"ORDER_NO" VARCHAR2(64 CHAR) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"CALLBACK_TYPE" VARCHAR2(16 CHAR) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"CALLBACK_STATUS" VARCHAR2(16 CHAR) COLLATE "USING_NLS_COMP", 
	"REFUND_ORDER_NO" VARCHAR2(64 CHAR) COLLATE "USING_NLS_COMP", 
	"MERCHANT_ORDER_NO" VARCHAR2(64 CHAR) COLLATE "USING_NLS_COMP", 
	"CHANNEL_ORDER_NO" VARCHAR2(128 CHAR) COLLATE "USING_NLS_COMP", 
	"MERCHANT_REFUND_NO" VARCHAR2(64 CHAR) COLLATE "USING_NLS_COMP", 
	"REFUND_NO" VARCHAR2(64 CHAR) COLLATE "USING_NLS_COMP", 
	"CHANNEL_REFUND_NO" VARCHAR2(128 CHAR) COLLATE "USING_NLS_COMP", 
	"PAY_TIME" VARCHAR2(14 CHAR) COLLATE "USING_NLS_COMP", 
	"REFUND_TIME" VARCHAR2(14 CHAR) COLLATE "USING_NLS_COMP", 
	"TOTAL_AMOUNT" NUMBER(12,0), 
	"CASH_AMOUNT" NUMBER(12,0), 
	"COUPON_AMOUNT" NUMBER(12,0), 
	"REFUND_AMOUNT" NUMBER(12,0), 
	"PAY_USER_ID" VARCHAR2(128 CHAR) COLLATE "USING_NLS_COMP", 
	"PAYMENT_VENDOR" VARCHAR2(16 CHAR) COLLATE "USING_NLS_COMP", 
	"TXN_DATE" VARCHAR2(8 CHAR) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"RAW_BODY" CLOB COLLATE "USING_NLS_COMP", 
	"HANDLE_STATUS" VARCHAR2(16 CHAR) COLLATE "USING_NLS_COMP", 
	"HANDLE_MSG" VARCHAR2(512 CHAR) COLLATE "USING_NLS_COMP", 
	"CREATE_TIME" TIMESTAMP (6) DEFAULT SYSTIMESTAMP NOT NULL ENABLE, 
	"DISCOUNT_INFO" VARCHAR2(2000 CHAR) COLLATE "USING_NLS_COMP", 
	 CONSTRAINT "PK_PAY_CALLBACK_LOG" PRIMARY KEY ("ID")
  USING INDEX PCTFREE 10 INITRANS 2 MAXTRANS 255 COMPUTE STATISTICS 
  STORAGE(INITIAL 65536 NEXT 1048576 MINEXTENTS 1 MAXEXTENTS 2147483645
  PCTINCREASE 0 FREELISTS 1 FREELIST GROUPS 1
  BUFFER_POOL DEFAULT FLASH_CACHE DEFAULT CELL_FLASH_CACHE DEFAULT)
  TABLESPACE "USERS"  ENABLE
   )  DEFAULT COLLATION "USING_NLS_COMP" PCTFREE 10 PCTUSED 40 INITRANS 1 MAXTRANS 255 
  STORAGE(
  BUFFER_POOL DEFAULT FLASH_CACHE DEFAULT CELL_FLASH_CACHE DEFAULT)
  TABLESPACE "USERS" 
 LOB ("RAW_BODY") STORE AS SECUREFILE (
  ENABLE STORAGE IN ROW CHUNK 8192
  NOCACHE LOGGING  NOCOMPRESS  KEEP_DUPLICATES 
  STORAGE(
  BUFFER_POOL DEFAULT FLASH_CACHE DEFAULT CELL_FLASH_CACHE DEFAULT)) 
  PARTITION BY RANGE ("TXN_DATE") 
 (PARTITION "P202606"  VALUES LESS THAN ('20260701') SEGMENT CREATION IMMEDIATE 
  PCTFREE 10 PCTUSED 40 INITRANS 1 MAXTRANS 255 
 NOCOMPRESS LOGGING 
  STORAGE(INITIAL 8388608 NEXT 1048576 MINEXTENTS 1 MAXEXTENTS 2147483645
  PCTINCREASE 0 FREELISTS 1 FREELIST GROUPS 1
  BUFFER_POOL DEFAULT FLASH_CACHE DEFAULT CELL_FLASH_CACHE DEFAULT)
  TABLESPACE "USERS" 
 LOB ("RAW_BODY") STORE AS SECUREFILE (
  TABLESPACE "USERS" ENABLE STORAGE IN ROW CHUNK 8192
  NOCACHE LOGGING  NOCOMPRESS  KEEP_DUPLICATES 
  STORAGE(INITIAL 8388608 NEXT 1048576 MINEXTENTS 1 MAXEXTENTS 2147483645
