-- QDITP.PAY_REFUND_DETAIL definition

CREATE TABLE "QDITP"."PAY_REFUND_DETAIL" 
   (	"ID" NUMBER(20,0) NOT NULL ENABLE, 
	"REFUND_ORDER_NO" VARCHAR2(64 CHAR) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"ORDER_NO" VARCHAR2(64 CHAR) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"REFUND_STATUS" VARCHAR2(16 CHAR) COLLATE "USING_NLS_COMP" DEFAULT 'INIT' NOT NULL ENABLE, 
