   COMMENT ON COLUMN "QDITP"."PAY_REFUND_DETAIL"."REFUND_STATUS" IS '退款状态：INIT初始化，PROCESSING处理中，SUCCESS成功，FAIL失败，RETRY待重试，CLOSED关闭';
