   COMMENT ON TABLE "QDITP"."PAY_REFUND_DETAIL"  IS '支付退款明细表';


-- QDITP.PAY_TXN_DETAIL definition

CREATE TABLE "QDITP"."PAY_TXN_DETAIL" 
   (	"ID" NUMBER(20,0) NOT NULL ENABLE, 
