	"PAY_TYPE" VARCHAR2(16 CHAR) COLLATE "USING_NLS_COMP" DEFAULT 'PAY' NOT NULL ENABLE, 
	"PAY_STATUS" VARCHAR2(16 CHAR) COLLATE "USING_NLS_COMP" DEFAULT 'INIT' NOT NULL ENABLE, 
