	"CASH_AMOUNT" NUMBER(12,0), 
	"COUPON_AMOUNT" NUMBER(12,0), 
	"REFUND_STATUS" VARCHAR2(16 CHAR) COLLATE "USING_NLS_COMP" DEFAULT 'NONE' NOT NULL ENABLE, 
