COMMENT ON COLUMN "QDITP"."PAY_TXN_DETAIL"."ORDER_NO" IS '地铁侧订单号，同时作为支付接口orderNo';
   COMMENT ON COLUMN "QDITP"."PAY_TXN_DETAIL"."PAY_TYPE" IS '交易类型：PAY支付，REFUND退款';
   COMMENT ON COLUMN "QDITP"."PAY_TXN_DETAIL"."PAY_STATUS" IS '支付状态：INIT初始化，PROCESSING处理中，SUCCESS成功，FAIL失败，RETRY待重试，CLOSED关闭';
   COMMENT ON COLUMN "QDITP"."PAY_TXN_DETAIL"."THIRD_USER_ID" IS '第三方用户ID，对应设备报文itpUserId转换后的用户标识';
   COMMENT ON COLUMN "QDITP"."PAY_TXN_DETAIL"."CARD_ID" IS '逻辑卡号';
   COMMENT ON COLUMN "QDITP"."PAY_TXN_DETAIL"."CARD_TYPE" IS '票卡类型';
   COMMENT ON COLUMN "QDITP"."PAY_TXN_DETAIL"."PAYMENT_VENDOR" IS '支付方式';
   COMMENT ON COLUMN "QDITP"."PAY_TXN_DETAIL"."REQUEST_SIGN_SEQ" IS '签约流水号或免密协议流水';
   COMMENT ON COLUMN "QDITP"."PAY_TXN_DETAIL"."AMOUNT" IS '请求支付金额，单位分';
   COMMENT ON COLUMN "QDITP"."PAY_TXN_DETAIL"."TOTAL_AMOUNT" IS '订单总金额，单位分';
   COMMENT ON COLUMN "QDITP"."PAY_TXN_DETAIL"."CASH_AMOUNT" IS '实付金额，单位分';
   COMMENT ON COLUMN "QDITP"."PAY_TXN_DETAIL"."COUPON_AMOUNT" IS '优惠金额，单位分';
   COMMENT ON COLUMN "QDITP"."PAY_TXN_DETAIL"."REFUND_STATUS" IS '退款状态：NONE未退款，PROCESSING退款中，PARTIAL部分退款，SUCCESS已全额退款，FAIL退款失败';
   COMMENT ON COLUMN "QDITP"."PAY_TXN_DETAIL"."REFUND_AMOUNT" IS '已退款总金额，单位分';
   COMMENT ON COLUMN "QDITP"."PAY_TXN_DETAIL"."LAST_REFUND_TIME" IS '最近一次退款完成时间';
   COMMENT ON COLUMN "QDITP"."PAY_TXN_DETAIL"."MERCHANT_ORDER_NO" IS '商户订单号';
   COMMENT ON COLUMN "QDITP"."PAY_TXN_DETAIL"."CHANNEL_ORDER_NO" IS '渠道订单号';
   COMMENT ON COLUMN "QDITP"."PAY_TXN_DETAIL"."PAY_USER_ID" IS '支付渠道账户或买家账户';
   COMMENT ON COLUMN "QDITP"."PAY_TXN_DETAIL"."REQUEST_COUNT" IS '已发起支付请求次数';
   COMMENT ON COLUMN "QDITP"."PAY_TXN_DETAIL"."NEXT_REQUEST_TIME" IS '下次允许重试支付时间';
   COMMENT ON COLUMN "QDITP"."PAY_TXN_DETAIL"."LAST_REQUEST_TIME" IS '最近一次发起支付时间';
   COMMENT ON COLUMN "QDITP"."PAY_TXN_DETAIL"."FIRST_REQUEST_TIME" IS '首次发起支付时间';
   COMMENT ON COLUMN "QDITP"."PAY_TXN_DETAIL"."RESPONSE_TIME" IS '最近一次收到支付响应时间';
   COMMENT ON COLUMN "QDITP"."PAY_TXN_DETAIL"."PAY_TIME" IS '支付完成时间，格式YYYYMMDDHH24MISS';
   COMMENT ON COLUMN "QDITP"."PAY_TXN_DETAIL"."TXN_DATE" IS '订单日期，格式YYYYMMDD，用于月分区';
   COMMENT ON COLUMN "QDITP"."PAY_TXN_DETAIL"."DISCOUNT_INFO" IS '优惠详情JSON数组，来自支付平台回调';
   COMMENT ON COLUMN "QDITP"."PAY_TXN_DETAIL"."DEBIT_REQUEST_RESULT" IS '扣款结果：pay-sign返回的扣款执行结果';
   COMMENT ON COLUMN "QDITP"."PAY_TXN_DETAIL"."DISCOUNT_FEE" IS '折扣金额：单位分';
   COMMENT ON COLUMN "QDITP"."PAY_TXN_DETAIL"."TRANS_IN" IS '入账账户/商户号（支付平台 data.transIn）';
   COMMENT ON COLUMN "QDITP"."PAY_TXN_DETAIL"."PAY_CENTER_ORDER_NO" IS '支付中心支付订单号，退款报文的原支付订单号取此列';
   COMMENT ON TABLE "QDITP"."PAY_TXN_DETAIL"  IS '支付交易明细表';


-- QDITP.QRCODE_STATUS definition

CREATE TABLE "QDITP"."QRCODE_STATUS" 
   (	"CARD_ID" VARCHAR2(32) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"USE_COUNT" NUMBER(10,0), 
	"CHANNEL" VARCHAR2(4) COLLATE "USING_NLS_COMP", 
	"CODE_STATUS" VARCHAR2(4) COLLATE "USING_NLS_COMP", 
	"GATE_IN_TIME" VARCHAR2(14) COLLATE "USING_NLS_COMP", 
	"GATE_IN_STATION" VARCHAR2(4) COLLATE "USING_NLS_COMP", 
	"LAST_TXN_TIME" VARCHAR2(14) COLLATE "USING_NLS_COMP", 
	"LAST_TXN_STATION" VARCHAR2(4) COLLATE "USING_NLS_COMP", 
	"TXN_SEQ" VARCHAR2(64) COLLATE "USING_NLS_COMP", 
	"CREATE_TIME" TIMESTAMP (6), 
	"UPDATE_TIME" TIMESTAMP (6), 
	"GATE_STATUS" VARCHAR2(32) COLLATE "USING_NLS_COMP", 
	"CARD_ID_TAIL" VARCHAR2(2 CHAR) COLLATE "USING_NLS_COMP" GENERATED ALWAYS AS (SUBSTR("CARD_ID",(-2))) VIRTUAL , 
	"TRX_AMOUNT" NUMBER(12,0), 
	 CONSTRAINT "PK_QRCODE_STATUS" PRIMARY KEY ("CARD_ID")
  USING INDEX PCTFREE 10 INITRANS 2 MAXTRANS 255 COMPUTE STATISTICS 
  STORAGE(INITIAL 65536 NEXT 1048576 MINEXTENTS 1 MAXEXTENTS 2147483645
  PCTINCREASE 0 FREELISTS 1 FREELIST GROUPS 1
  BUFFER_POOL DEFAULT FLASH_CACHE DEFAULT CELL_FLASH_CACHE DEFAULT)
  TABLESPACE "USERS"  ENABLE
   )  DEFAULT COLLATION "USING_NLS_COMP" PCTFREE 10 PCTUSED 40 INITRANS 1 MAXTRANS 255 
  STORAGE(
  BUFFER_POOL DEFAULT FLASH_CACHE DEFAULT CELL_FLASH_CACHE DEFAULT)
  TABLESPACE "USERS" 
  PARTITION BY LIST ("CARD_ID_TAIL") 
 (PARTITION "P_00"  VALUES ('00') SEGMENT CREATION IMMEDIATE 
  PCTFREE 10 PCTUSED 40 INITRANS 1 MAXTRANS 255 
 NOCOMPRESS LOGGING 
  STORAGE(INITIAL 8388608 NEXT 1048576 MINEXTENTS 1 MAXEXTENTS 2147483645
  PCTINCREASE 0 FREELISTS 1 FREELIST GROUPS 1
  BUFFER_POOL DEFAULT FLASH_CACHE DEFAULT CELL_FLASH_CACHE DEFAULT)
  TABLESPACE "USERS" , 
