COMMENT ON COLUMN "QDITP"."QRCODE_STATUS"."CARD_ID" IS '二维码卡号';
   COMMENT ON COLUMN "QDITP"."QRCODE_STATUS"."USE_COUNT" IS '使用次数';
   COMMENT ON COLUMN "QDITP"."QRCODE_STATUS"."CHANNEL" IS '渠道';
   COMMENT ON COLUMN "QDITP"."QRCODE_STATUS"."CODE_STATUS" IS '二维码状态';
   COMMENT ON COLUMN "QDITP"."QRCODE_STATUS"."GATE_IN_TIME" IS '进站时间，格式为yyyymmddhh24miss';
   COMMENT ON COLUMN "QDITP"."QRCODE_STATUS"."GATE_IN_STATION" IS '进站车站';
   COMMENT ON COLUMN "QDITP"."QRCODE_STATUS"."LAST_TXN_TIME" IS '最后交易时间，格式为yyyymmddhh24miss';
   COMMENT ON TABLE "QDITP"."QRCODE_STATUS"  IS '二维码状态表';


-- QDITP.QRCODE_SUPPLEMENT_REQUEST definition

CREATE TABLE "QDITP"."QRCODE_SUPPLEMENT_REQUEST" 
   (	"CARD_ID" VARCHAR2(32) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"TXN_SEQ" VARCHAR2(32) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"ADVICE_OPT" VARCHAR2(8) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"CODE_STATUS_SNAPSHOT" VARCHAR2(8) COLLATE "USING_NLS_COMP", 
	"HANDLE_STATION_CODE" VARCHAR2(16) COLLATE "USING_NLS_COMP", 
	"HANDLE_DATE_TIME" VARCHAR2(20) COLLATE "USING_NLS_COMP", 
	"TRX_AMOUNT" VARCHAR2(16) COLLATE "USING_NLS_COMP", 
	"HANDLE_STATUS" VARCHAR2(16) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"FAIL_REASON" VARCHAR2(256) COLLATE "USING_NLS_COMP", 
	"RETRY_COUNT" NUMBER(6,0) DEFAULT 0 NOT NULL ENABLE, 
	"CREATE_TIME" DATE DEFAULT SYSDATE NOT NULL ENABLE, 
	"UPDATE_TIME" DATE DEFAULT SYSDATE NOT NULL ENABLE
   )  DEFAULT COLLATION "USING_NLS_COMP" SEGMENT CREATION IMMEDIATE 
  PCTFREE 10 PCTUSED 40 INITRANS 1 MAXTRANS 255 
 NOCOMPRESS LOGGING
  STORAGE(INITIAL 65536 NEXT 1048576 MINEXTENTS 1 MAXEXTENTS 2147483645
  PCTINCREASE 0 FREELISTS 1 FREELIST GROUPS 1
  BUFFER_POOL DEFAULT FLASH_CACHE DEFAULT CELL_FLASH_CACHE DEFAULT)
  TABLESPACE "USERS" ;


-- QDITP.QRCODE_TXN_DETAIL definition

CREATE TABLE "QDITP"."QRCODE_TXN_DETAIL" 
   (	"ID" NUMBER(20,0) NOT NULL ENABLE, 
	"DEVICE_ID" VARCHAR2(16 CHAR) COLLATE "USING_NLS_COMP", 
	"ITP_USER_ID" VARCHAR2(64 CHAR) COLLATE "USING_NLS_COMP", 
	"TRX_TYPE" VARCHAR2(4 CHAR) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"ISSUE_CHANNEL_CODE" VARCHAR2(8 CHAR) COLLATE "USING_NLS_COMP", 
	"SIGN_CHANNEL_CODE" VARCHAR2(8 CHAR) COLLATE "USING_NLS_COMP", 
	"CARD_ID" VARCHAR2(32 CHAR) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"CARD_TYPE" VARCHAR2(8 CHAR) COLLATE "USING_NLS_COMP", 
	"HANDLE_DATE_TIME" VARCHAR2(14 CHAR) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"TXN_DATE" VARCHAR2(8 CHAR) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"HANDLE_STATION_CODE" VARCHAR2(16 CHAR) COLLATE "USING_NLS_COMP", 
	"TRX_AMOUNT" NUMBER(12,0), 
	"OVERTIME_AMOUNT" NUMBER(12,0), 
	"LAST_TICKET_STATUS" VARCHAR2(4 CHAR) COLLATE "USING_NLS_COMP", 
	"HANDLE_RESULT_CODE" VARCHAR2(8 CHAR) COLLATE "USING_NLS_COMP", 
	"LAST_HANDLE_STATION_CODE" VARCHAR2(16 CHAR) COLLATE "USING_NLS_COMP", 
	"LAST_HANDLE_DATE_TIME" VARCHAR2(14 CHAR) COLLATE "USING_NLS_COMP", 
	"TICKET_TRANS_SEQ" VARCHAR2(64 CHAR) COLLATE "USING_NLS_COMP", 
	"RESERVE1" VARCHAR2(512 CHAR) COLLATE "USING_NLS_COMP", 
	"RESERVE2" VARCHAR2(512 CHAR) COLLATE "USING_NLS_COMP", 
	"CREATE_TIME" TIMESTAMP (6) DEFAULT SYSTIMESTAMP NOT NULL ENABLE, 
	 CONSTRAINT "PK_QRCODE_TXN_DETAIL" PRIMARY KEY ("ID")
  USING INDEX PCTFREE 10 INITRANS 2 MAXTRANS 255 COMPUTE STATISTICS 
  STORAGE(INITIAL 65536 NEXT 1048576 MINEXTENTS 1 MAXEXTENTS 2147483645
  PCTINCREASE 0 FREELISTS 1 FREELIST GROUPS 1
  BUFFER_POOL DEFAULT FLASH_CACHE DEFAULT CELL_FLASH_CACHE DEFAULT)
  TABLESPACE "USERS"  ENABLE
   )  DEFAULT COLLATION "USING_NLS_COMP" PCTFREE 10 PCTUSED 40 INITRANS 1 MAXTRANS 255 
  STORAGE(
  BUFFER_POOL DEFAULT FLASH_CACHE DEFAULT CELL_FLASH_CACHE DEFAULT)
  TABLESPACE "USERS" 
  PARTITION BY RANGE ("TXN_DATE") 
 (PARTITION "P202606"  VALUES LESS THAN ('20260701') SEGMENT CREATION IMMEDIATE 
  PCTFREE 10 PCTUSED 40 INITRANS 1 MAXTRANS 255 
 NOCOMPRESS LOGGING 
  STORAGE(INITIAL 8388608 NEXT 1048576 MINEXTENTS 1 MAXEXTENTS 2147483645
  PCTINCREASE 0 FREELISTS 1 FREELIST GROUPS 1
  BUFFER_POOL DEFAULT FLASH_CACHE DEFAULT CELL_FLASH_CACHE DEFAULT)
  TABLESPACE "USERS" , 
 PARTITION "P202607"  VALUES LESS THAN ('20260801') SEGMENT CREATION IMMEDIATE 
  PCTFREE 10 PCTUSED 40 INITRANS 1 MAXTRANS 255 
 NOCOMPRESS LOGGING 
  STORAGE(INITIAL 8388608 NEXT 1048576 MINEXTENTS 1 MAXEXTENTS 2147483645
  PCTINCREASE 0 FREELISTS 1 FREELIST GROUPS 1
  BUFFER_POOL DEFAULT FLASH_CACHE DEFAULT CELL_FLASH_CACHE DEFAULT)
  TABLESPACE "USERS" , 
 PARTITION "P202608"  VALUES LESS THAN ('20260901') SEGMENT CREATION IMMEDIATE 
  PCTFREE 10 PCTUSED 40 INITRANS 1 MAXTRANS 255 
 NOCOMPRESS LOGGING 
  STORAGE(INITIAL 8388608 NEXT 1048576 MINEXTENTS 1 MAXEXTENTS 2147483645
  PCTINCREASE 0 FREELISTS 1 FREELIST GROUPS 1
  BUFFER_POOL DEFAULT FLASH_CACHE DEFAULT CELL_FLASH_CACHE DEFAULT)
