-- QDITP.SYS_NOTICE definition

CREATE TABLE "QDITP"."SYS_NOTICE" 
   (	"NOTICE_ID" NUMBER(10,0) GENERATED BY DEFAULT ON NULL AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 10 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE, 
	"NOTICE_TITLE" VARCHAR2(50 CHAR) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"NOTICE_TYPE" CHAR(1 CHAR) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"NOTICE_CONTENT" CLOB COLLATE "USING_NLS_COMP", 
	"STATUS" CHAR(1 CHAR) COLLATE "USING_NLS_COMP" DEFAULT '0', 
	"CREATE_BY" VARCHAR2(64 CHAR) COLLATE "USING_NLS_COMP", 
	"CREATE_TIME" DATE, 
	"UPDATE_BY" VARCHAR2(64 CHAR) COLLATE "USING_NLS_COMP", 
	"UPDATE_TIME" DATE, 
	"REMARK" VARCHAR2(255 CHAR) COLLATE "USING_NLS_COMP", 
	 PRIMARY KEY ("NOTICE_ID")
  USING INDEX PCTFREE 10 INITRANS 2 MAXTRANS 255 COMPUTE STATISTICS 
  STORAGE(INITIAL 65536 NEXT 1048576 MINEXTENTS 1 MAXEXTENTS 2147483645
  PCTINCREASE 0 FREELISTS 1 FREELIST GROUPS 1
  BUFFER_POOL DEFAULT FLASH_CACHE DEFAULT CELL_FLASH_CACHE DEFAULT)
  TABLESPACE "USERS"  ENABLE
   )  DEFAULT COLLATION "USING_NLS_COMP" SEGMENT CREATION IMMEDIATE 
  PCTFREE 10 PCTUSED 40 INITRANS 1 MAXTRANS 255 
 NOCOMPRESS LOGGING
  STORAGE(INITIAL 65536 NEXT 1048576 MINEXTENTS 1 MAXEXTENTS 2147483645
  PCTINCREASE 0 FREELISTS 1 FREELIST GROUPS 1
  BUFFER_POOL DEFAULT FLASH_CACHE DEFAULT CELL_FLASH_CACHE DEFAULT)
  TABLESPACE "USERS" 
 LOB ("NOTICE_CONTENT") STORE AS SECUREFILE (
  TABLESPACE "USERS" ENABLE STORAGE IN ROW CHUNK 8192
  NOCACHE LOGGING  NOCOMPRESS  KEEP_DUPLICATES 
  STORAGE(INITIAL 106496 NEXT 1048576 MINEXTENTS 1 MAXEXTENTS 2147483645
  PCTINCREASE 0
  BUFFER_POOL DEFAULT FLASH_CACHE DEFAULT CELL_FLASH_CACHE DEFAULT)) ;

COMMENT ON COLUMN "QDITP"."SYS_NOTICE"."NOTICE_ID" IS '公告ID';
   COMMENT ON COLUMN "QDITP"."SYS_NOTICE"."NOTICE_TITLE" IS '公告标题';
