   COMMENT ON COLUMN "QDITP"."SYS_NOTICE"."UPDATE_BY" IS '更新者';
   COMMENT ON COLUMN "QDITP"."SYS_NOTICE"."UPDATE_TIME" IS '更新时间';
   COMMENT ON COLUMN "QDITP"."SYS_NOTICE"."REMARK" IS '备注';
