-- QDITP.SYS_USER definition

CREATE TABLE "QDITP"."SYS_USER" 
   (	"USER_ID" NUMBER(19,0) GENERATED BY DEFAULT ON NULL AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 100 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE, 
	"DEPT_ID" NUMBER(19,0), 
	"USER_NAME" VARCHAR2(30 CHAR) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"NICK_NAME" VARCHAR2(30 CHAR) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"USER_TYPE" VARCHAR2(2 CHAR) COLLATE "USING_NLS_COMP" DEFAULT '00', 
	"EMAIL" VARCHAR2(50 CHAR) COLLATE "USING_NLS_COMP", 
	"PHONENUMBER" VARCHAR2(11 CHAR) COLLATE "USING_NLS_COMP", 
	"SEX" CHAR(1 CHAR) COLLATE "USING_NLS_COMP" DEFAULT '0', 
	"AVATAR" VARCHAR2(100 CHAR) COLLATE "USING_NLS_COMP", 
	"PASSWORD" VARCHAR2(100 CHAR) COLLATE "USING_NLS_COMP", 
	"STATUS" CHAR(1 CHAR) COLLATE "USING_NLS_COMP" DEFAULT '0', 
	"DEL_FLAG" CHAR(1 CHAR) COLLATE "USING_NLS_COMP" DEFAULT '0', 
	"LOGIN_IP" VARCHAR2(128 CHAR) COLLATE "USING_NLS_COMP", 
	"LOGIN_DATE" DATE, 
	"PWD_UPDATE_DATE" DATE, 
	"CREATE_BY" VARCHAR2(64 CHAR) COLLATE "USING_NLS_COMP", 
	"CREATE_TIME" DATE, 
	"UPDATE_BY" VARCHAR2(64 CHAR) COLLATE "USING_NLS_COMP", 
	"UPDATE_TIME" DATE, 
	"REMARK" VARCHAR2(500 CHAR) COLLATE "USING_NLS_COMP", 
	 PRIMARY KEY ("USER_ID")
  USING INDEX PCTFREE 10 INITRANS 2 MAXTRANS 255 COMPUTE STATISTICS 
  STORAGE(INITIAL 65536 NEXT 1048576 MINEXTENTS 1 MAXEXTENTS 2147483645
  PCTINCREASE 0 FREELISTS 1 FREELIST GROUPS 1
  BUFFER_POOL DEFAULT FLASH_CACHE DEFAULT CELL_FLASH_CACHE DEFAULT)
  TABLESPACE "USERS"  ENABLE
   )  DEFAULT COLLATION "USING_NLS_COMP" SEGMENT CREATION IMMEDIATE 
  PCTFREE 10 PCTUSED 40 INITRANS 1 MAXTRANS 255 
 NOCOMPRESS LOGGING
  STORAGE(INITIAL 65536 NEXT 1048576 MINEXTENTS 1 MAXEXTENTS 2147483645
  PCTINCREASE 0 FREELISTS 1 FREELIST GROUPS 1
  BUFFER_POOL DEFAULT FLASH_CACHE DEFAULT CELL_FLASH_CACHE DEFAULT)
  TABLESPACE "USERS" ;

COMMENT ON COLUMN "QDITP"."SYS_USER"."USER_ID" IS '用户ID';
   COMMENT ON COLUMN "QDITP"."SYS_USER"."DEPT_ID" IS '部门ID';
   COMMENT ON COLUMN "QDITP"."SYS_USER"."USER_NAME" IS '用户账号';
   COMMENT ON COLUMN "QDITP"."SYS_USER"."NICK_NAME" IS '用户昵称';
   COMMENT ON COLUMN "QDITP"."SYS_USER"."USER_TYPE" IS '用户类型（00系统用户）';
   COMMENT ON COLUMN "QDITP"."SYS_USER"."EMAIL" IS '用户邮箱';
   COMMENT ON COLUMN "QDITP"."SYS_USER"."PHONENUMBER" IS '手机号码';
   COMMENT ON COLUMN "QDITP"."SYS_USER"."SEX" IS '用户性别（0男 1女 2未知）';
   COMMENT ON COLUMN "QDITP"."SYS_USER"."AVATAR" IS '头像地址';
   COMMENT ON COLUMN "QDITP"."SYS_USER"."PASSWORD" IS '密码';
   COMMENT ON COLUMN "QDITP"."SYS_USER"."STATUS" IS '账号状态（0正常 1停用）';
   COMMENT ON COLUMN "QDITP"."SYS_USER"."DEL_FLAG" IS '删除标志（0代表存在 2代表删除）';
   COMMENT ON COLUMN "QDITP"."SYS_USER"."LOGIN_IP" IS '最后登录IP';
   COMMENT ON COLUMN "QDITP"."SYS_USER"."LOGIN_DATE" IS '最后登录时间';
   COMMENT ON COLUMN "QDITP"."SYS_USER"."PWD_UPDATE_DATE" IS '密码最后更新时间';
   COMMENT ON COLUMN "QDITP"."SYS_USER"."CREATE_BY" IS '创建者';
   COMMENT ON COLUMN "QDITP"."SYS_USER"."CREATE_TIME" IS '创建时间';
   COMMENT ON COLUMN "QDITP"."SYS_USER"."UPDATE_BY" IS '更新者';
   COMMENT ON COLUMN "QDITP"."SYS_USER"."UPDATE_TIME" IS '更新时间';
   COMMENT ON COLUMN "QDITP"."SYS_USER"."REMARK" IS '备注';
   COMMENT ON TABLE "QDITP"."SYS_USER"  IS '用户信息表';


