	"CARD_TYPE" VARCHAR2(16) COLLATE "USING_NLS_COMP", 
	"SHOW_TYPE" VARCHAR2(16) COLLATE "USING_NLS_COMP", 
	"TICKET_PRICE" NUMBER(12,0), 
	"TICKET_COUNT" NUMBER(8,0), 
	"TOTAL_AMOUNT" NUMBER(12,0), 
	"ORDER_SOURCE" VARCHAR2(8) COLLATE "USING_NLS_COMP", 
	"ORDER_STATUS" VARCHAR2(32) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"PAY_STATUS" VARCHAR2(32) COLLATE "USING_NLS_COMP", 
	"CREATE_TIME" TIMESTAMP (6) DEFAULT SYSTIMESTAMP, 
	"UPDATE_TIME" TIMESTAMP (6) DEFAULT SYSTIMESTAMP, 
	"THIRD_USER_ID" VARCHAR2(64) COLLATE "USING_NLS_COMP", 
	"PAY_AMOUNT" NUMBER(12,0), 
	"PAY_CHANNEL_CODE" VARCHAR2(16) COLLATE "USING_NLS_COMP", 
	"CHANNEL_TYPE" VARCHAR2(8) COLLATE "USING_NLS_COMP", 
	"PAY_SCENE" VARCHAR2(16) COLLATE "USING_NLS_COMP", 
	"TRADE_NO" VARCHAR2(128) COLLATE "USING_NLS_COMP", 
	"PAYMENT_ORDER_NO" VARCHAR2(128) COLLATE "USING_NLS_COMP", 
	"PAY_DATE" TIMESTAMP (6), 
	"CASH_AMOUNT" NUMBER(12,0), 
	"COUPON_AMOUNT" NUMBER(12,0), 
	 PRIMARY KEY ("ID")
  USING INDEX PCTFREE 10 INITRANS 2 MAXTRANS 255 COMPUTE STATISTICS 
  STORAGE(INITIAL 65536 NEXT 1048576 MINEXTENTS 1 MAXEXTENTS 2147483645
  PCTINCREASE 0 FREELISTS 1 FREELIST GROUPS 1
  BUFFER_POOL DEFAULT FLASH_CACHE DEFAULT CELL_FLASH_CACHE DEFAULT)
  TABLESPACE "USERS"  ENABLE, 
	 UNIQUE ("ORDER_NO")
  USING INDEX PCTFREE 10 INITRANS 2 MAXTRANS 255 COMPUTE STATISTICS 
  STORAGE(INITIAL 65536 NEXT 1048576 MINEXTENTS 1 MAXEXTENTS 2147483645
  PCTINCREASE 0 FREELISTS 1 FREELIST GROUPS 1
  BUFFER_POOL DEFAULT FLASH_CACHE DEFAULT CELL_FLASH_CACHE DEFAULT)
