COMMENT ON COLUMN "QDITP"."TRAVEL_TICKET_ORDER"."ID" IS '主键ID';
   COMMENT ON COLUMN "QDITP"."TRAVEL_TICKET_ORDER"."ORDER_NO" IS '旅游票单号，前缀0T';
   COMMENT ON COLUMN "QDITP"."TRAVEL_TICKET_ORDER"."USER_ID" IS 'APP用户编号';
   COMMENT ON COLUMN "QDITP"."TRAVEL_TICKET_ORDER"."CARD_TYPE" IS 'APP侧卡类型';
   COMMENT ON COLUMN "QDITP"."TRAVEL_TICKET_ORDER"."SHOW_TYPE" IS '展示类型';
   COMMENT ON COLUMN "QDITP"."TRAVEL_TICKET_ORDER"."TICKET_PRICE" IS '单张票价，单位分';
   COMMENT ON COLUMN "QDITP"."TRAVEL_TICKET_ORDER"."TICKET_COUNT" IS '购买数量，即内含日票张数';
   COMMENT ON COLUMN "QDITP"."TRAVEL_TICKET_ORDER"."TOTAL_AMOUNT" IS '总金额，单位分，服务端按TICKET_PRICE乘TICKET_COUNT重算';
   COMMENT ON COLUMN "QDITP"."TRAVEL_TICKET_ORDER"."ORDER_SOURCE" IS '订单来源';
   COMMENT ON COLUMN "QDITP"."TRAVEL_TICKET_ORDER"."ORDER_STATUS" IS '订单状态：CREATED/PAYING/PAID/PAY_FAILED/CANCELED/REFUNDING/REFUNDED';
   COMMENT ON COLUMN "QDITP"."TRAVEL_TICKET_ORDER"."PAY_STATUS" IS '支付状态：INIT/PAYING/PAID/FAIL';
   COMMENT ON COLUMN "QDITP"."TRAVEL_TICKET_ORDER"."CREATE_TIME" IS '创建时间';
   COMMENT ON COLUMN "QDITP"."TRAVEL_TICKET_ORDER"."UPDATE_TIME" IS '更新时间';
   COMMENT ON COLUMN "QDITP"."TRAVEL_TICKET_ORDER"."CASH_AMOUNT" IS '支付中心回调回传的实付现金金额（分）；原样落库，不做与总额的匹配校验';
   COMMENT ON COLUMN "QDITP"."TRAVEL_TICKET_ORDER"."COUPON_AMOUNT" IS '支付中心回调回传的优惠金额（分）；原样落库，不做与总额的匹配校验';
   COMMENT ON TABLE "QDITP"."TRAVEL_TICKET_ORDER"  IS '旅游票聚合主单表，内含的每张日票落在DAILY_TICKET_ORDER';


-- QDITP.USER_ACC_EMPLOYEE_CARD definition

CREATE TABLE "QDITP"."USER_ACC_EMPLOYEE_CARD" 
   (	"ID" NUMBER(22,0) GENERATED BY DEFAULT AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE, 
	"CARD_NO" VARCHAR2(32 CHAR) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"THIRD_USER_ID" VARCHAR2(128 CHAR) COLLATE "USING_NLS_COMP", 
	"PHONE" VARCHAR2(64 CHAR) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"EMPLOYEE_NAME" VARCHAR2(256 CHAR) COLLATE "USING_NLS_COMP", 
	"ID_CARD_NO" VARCHAR2(128 CHAR) COLLATE "USING_NLS_COMP", 
	"COMPANY" VARCHAR2(256 CHAR) COLLATE "USING_NLS_COMP", 
	"CENTER" VARCHAR2(256 CHAR) COLLATE "USING_NLS_COMP", 
	"DEPARTMENT" VARCHAR2(256 CHAR) COLLATE "USING_NLS_COMP", 
	"POSITION" VARCHAR2(256 CHAR) COLLATE "USING_NLS_COMP", 
	"PHOTO_URL" CLOB COLLATE "USING_NLS_COMP", 
	"CARD_STATUS" NUMBER(1,0) NOT NULL ENABLE, 
	"OPEN_TMS" TIMESTAMP (6), 
	"CANCEL_TMS" TIMESTAMP (6), 
	"CREATE_TMS" TIMESTAMP (6) NOT NULL ENABLE, 
	"UPDATE_TMS" TIMESTAMP (6) NOT NULL ENABLE, 
	 CONSTRAINT "CK_UAEC_CARD_STATUS" CHECK (CARD_STATUS IN (1, 2, 3, 4)) ENABLE, 
	 CONSTRAINT "PK_USER_ACC_EMPLOYEE_CARD" PRIMARY KEY ("ID")
  USING INDEX PCTFREE 10 INITRANS 2 MAXTRANS 255 COMPUTE STATISTICS 
  STORAGE(INITIAL 65536 NEXT 1048576 MINEXTENTS 1 MAXEXTENTS 2147483645
  PCTINCREASE 0 FREELISTS 1 FREELIST GROUPS 1
  BUFFER_POOL DEFAULT FLASH_CACHE DEFAULT CELL_FLASH_CACHE DEFAULT)
  TABLESPACE "USERS"  ENABLE
   )  DEFAULT COLLATION "USING_NLS_COMP" SEGMENT CREATION IMMEDIATE 
  PCTFREE 10 PCTUSED 40 INITRANS 1 MAXTRANS 255 
 NOCOMPRESS LOGGING
  STORAGE(INITIAL 65536 NEXT 1048576 MINEXTENTS 1 MAXEXTENTS 2147483645
  PCTINCREASE 0 FREELISTS 1 FREELIST GROUPS 1
  BUFFER_POOL DEFAULT FLASH_CACHE DEFAULT CELL_FLASH_CACHE DEFAULT)
  TABLESPACE "USERS" 
 LOB ("PHOTO_URL") STORE AS SECUREFILE (
  TABLESPACE "USERS" ENABLE STORAGE IN ROW CHUNK 8192
  NOCACHE LOGGING  NOCOMPRESS  KEEP_DUPLICATES 
  STORAGE(INITIAL 106496 NEXT 1048576 MINEXTENTS 1 MAXEXTENTS 2147483645
  PCTINCREASE 0
  BUFFER_POOL DEFAULT FLASH_CACHE DEFAULT CELL_FLASH_CACHE DEFAULT)) ;

COMMENT ON COLUMN "QDITP"."USER_ACC_EMPLOYEE_CARD"."ID" IS '主键';
   COMMENT ON COLUMN "QDITP"."USER_ACC_EMPLOYEE_CARD"."CARD_NO" IS '员工号，对应员工码接口cardNo字段，唯一且不可变';
   COMMENT ON COLUMN "QDITP"."USER_ACC_EMPLOYEE_CARD"."THIRD_USER_ID" IS 'ITP/APP用户标识';
   COMMENT ON COLUMN "QDITP"."USER_ACC_EMPLOYEE_CARD"."PHONE" IS '绑定手机号，开通后不可变更';
   COMMENT ON COLUMN "QDITP"."USER_ACC_EMPLOYEE_CARD"."EMPLOYEE_NAME" IS '员工姓名';
   COMMENT ON COLUMN "QDITP"."USER_ACC_EMPLOYEE_CARD"."ID_CARD_NO" IS '身份证号';
   COMMENT ON COLUMN "QDITP"."USER_ACC_EMPLOYEE_CARD"."COMPANY" IS '所属公司';
   COMMENT ON COLUMN "QDITP"."USER_ACC_EMPLOYEE_CARD"."CENTER" IS '所属中心';
   COMMENT ON COLUMN "QDITP"."USER_ACC_EMPLOYEE_CARD"."DEPARTMENT" IS '所属部门';
   COMMENT ON COLUMN "QDITP"."USER_ACC_EMPLOYEE_CARD"."POSITION" IS '岗位';
   COMMENT ON COLUMN "QDITP"."USER_ACC_EMPLOYEE_CARD"."PHOTO_URL" IS '员工照片Base64内容，原始照片限制250KB';
   COMMENT ON COLUMN "QDITP"."USER_ACC_EMPLOYEE_CARD"."CARD_STATUS" IS '员工码状态：1-启用，2-禁用，3-未启用，4-注销';
   COMMENT ON COLUMN "QDITP"."USER_ACC_EMPLOYEE_CARD"."OPEN_TMS" IS '首次开通时间';
   COMMENT ON COLUMN "QDITP"."USER_ACC_EMPLOYEE_CARD"."CANCEL_TMS" IS '注销时间';
   COMMENT ON COLUMN "QDITP"."USER_ACC_EMPLOYEE_CARD"."CREATE_TMS" IS '创建时间';
   COMMENT ON COLUMN "QDITP"."USER_ACC_EMPLOYEE_CARD"."UPDATE_TMS" IS '更新时间';
   COMMENT ON TABLE "QDITP"."USER_ACC_EMPLOYEE_CARD"  IS 'ACC员工码信息表';


