COMMENT ON COLUMN "QDITP"."USER_ITP_REG_INFO"."ID" IS '主键';
   COMMENT ON COLUMN "QDITP"."USER_ITP_REG_INFO"."CARD_ID" IS '逻辑卡号';
   COMMENT ON COLUMN "QDITP"."USER_ITP_REG_INFO"."CARD_TYPE" IS '转换后的卡类型';
   COMMENT ON COLUMN "QDITP"."USER_ITP_REG_INFO"."THIRD_USER_ID" IS '第三方用户标识';
   COMMENT ON COLUMN "QDITP"."USER_ITP_REG_INFO"."THIRD_USER_ID_SUFFIX" IS '第三方用户标识后两位，分区字段';
   COMMENT ON COLUMN "QDITP"."USER_ITP_REG_INFO"."MSISDN" IS '手机号';
   COMMENT ON COLUMN "QDITP"."USER_ITP_REG_INFO"."REG_TMS" IS '注册时间';
   COMMENT ON COLUMN "QDITP"."USER_ITP_REG_INFO"."DEL_YN" IS '删除标识，1-有效，0-已注销';
   COMMENT ON COLUMN "QDITP"."USER_ITP_REG_INFO"."DEL_THIRD_USER_ID" IS '注销操作对应的第三方用户标识';
   COMMENT ON COLUMN "QDITP"."USER_ITP_REG_INFO"."UN_REG_TMS" IS '注销时间';
   COMMENT ON COLUMN "QDITP"."USER_ITP_REG_INFO"."USER_NAME" IS '用户姓名';
   COMMENT ON COLUMN "QDITP"."USER_ITP_REG_INFO"."USER_ID" IS '证件号';
   COMMENT ON COLUMN "QDITP"."USER_ITP_REG_INFO"."CARD_ISSUE_CODE" IS '发行渠道编码，仅0001正常渠道/0007支付宝出行，参与码体拼装，取右2位落码体渠道位';
   COMMENT ON COLUMN "QDITP"."USER_ITP_REG_INFO"."THIRD_PAY_ID" IS '第三方支付用户标识';
   COMMENT ON COLUMN "QDITP"."USER_ITP_REG_INFO"."CHANNEL" IS '渠道编码';
   COMMENT ON COLUMN "QDITP"."USER_ITP_REG_INFO"."REQ_CONTRACT_NO" IS '签约请求号';
   COMMENT ON COLUMN "QDITP"."USER_ITP_REG_INFO"."ITP_CARD_TYPE" IS 'APP入参卡类型';
   COMMENT ON COLUMN "QDITP"."USER_ITP_REG_INFO"."HCE_DATA" IS 'HCE卡数据，开户时生成并由闸机交易reserve1更新';
   COMMENT ON COLUMN "QDITP"."USER_ITP_REG_INFO"."COMPANION_FLAG" IS '卡用途，N-主卡，Y-同行票，C-第三方票；新开户数量限制由TICKET_LIMIT决定';
   COMMENT ON COLUMN "QDITP"."USER_ITP_REG_INFO"."ISSUE_ORG_CODE" IS '票卡所属方，APP开户上送原值，参与唯一卡查重，不校验机构字典，不参与码体拼装';
   COMMENT ON COLUMN "QDITP"."USER_ITP_REG_INFO"."TICKET_LIMIT" IS '开卡数量限制，1-同用户同所属方同卡类型唯一卡，2-每次发新卡；NULL保留历史普通卡唯一、Y/C多卡规则';
   COMMENT ON TABLE "QDITP"."USER_ITP_REG_INFO"  IS 'ITP用户注册信息表';


-- QDITP.USER_ITP_REG_LOG definition

CREATE TABLE "QDITP"."USER_ITP_REG_LOG" 
   (	"ID" NUMBER(10,0) GENERATED BY DEFAULT AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE, 
	"CARD_ID" VARCHAR2(64 CHAR) COLLATE "USING_NLS_COMP", 
	"CARD_TYPE" VARCHAR2(32 CHAR) COLLATE "USING_NLS_COMP", 
	"THIRD_USER_ID" VARCHAR2(64 CHAR) COLLATE "USING_NLS_COMP", 
	"MSISDN" VARCHAR2(32 CHAR) COLLATE "USING_NLS_COMP", 
	"OPER_DATE_TIME" TIMESTAMP (6), 
	"OPER_TYPE" NUMBER(10,0), 
	 CONSTRAINT "PK_USER_ITP_REG_LOG" PRIMARY KEY ("ID")
  USING INDEX PCTFREE 10 INITRANS 2 MAXTRANS 255 COMPUTE STATISTICS 
  STORAGE(INITIAL 65536 NEXT 1048576 MINEXTENTS 1 MAXEXTENTS 2147483645
  PCTINCREASE 0 FREELISTS 1 FREELIST GROUPS 1
  BUFFER_POOL DEFAULT FLASH_CACHE DEFAULT CELL_FLASH_CACHE DEFAULT)
  TABLESPACE "USERS"  ENABLE
   )  DEFAULT COLLATION "USING_NLS_COMP" SEGMENT CREATION IMMEDIATE 
  PCTFREE 10 PCTUSED 40 INITRANS 1 MAXTRANS 255 
 NOCOMPRESS LOGGING
  STORAGE(INITIAL 65536 NEXT 1048576 MINEXTENTS 1 MAXEXTENTS 2147483645
  PCTINCREASE 0 FREELISTS 1 FREELIST GROUPS 1
  BUFFER_POOL DEFAULT FLASH_CACHE DEFAULT CELL_FLASH_CACHE DEFAULT)
  TABLESPACE "USERS" ;

COMMENT ON COLUMN "QDITP"."USER_ITP_REG_LOG"."ID" IS '主键';
   COMMENT ON COLUMN "QDITP"."USER_ITP_REG_LOG"."CARD_ID" IS '逻辑卡号';
   COMMENT ON COLUMN "QDITP"."USER_ITP_REG_LOG"."CARD_TYPE" IS '卡类型';
   COMMENT ON COLUMN "QDITP"."USER_ITP_REG_LOG"."THIRD_USER_ID" IS '第三方用户标识';
   COMMENT ON COLUMN "QDITP"."USER_ITP_REG_LOG"."MSISDN" IS '手机号';
   COMMENT ON COLUMN "QDITP"."USER_ITP_REG_LOG"."OPER_DATE_TIME" IS '操作时间';
   COMMENT ON COLUMN "QDITP"."USER_ITP_REG_LOG"."OPER_TYPE" IS '操作类型';
   COMMENT ON TABLE "QDITP"."USER_ITP_REG_LOG"  IS 'ITP用户注册日志表';


-- QDITP.USER_PHONE_CHANGE_LOG definition

CREATE TABLE "QDITP"."USER_PHONE_CHANGE_LOG" 
   (	"ID" NUMBER NOT NULL ENABLE, 
	"THIRD_USER_ID" VARCHAR2(128 CHAR) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"USER_TYPE" VARCHAR2(32 CHAR) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"OLD_MSISDN" VARCHAR2(32 CHAR) COLLATE "USING_NLS_COMP", 
	"NEW_MSISDN" VARCHAR2(32 CHAR) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"OPER_TYPE" VARCHAR2(32 CHAR) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"OPER_TIME" TIMESTAMP (6) NOT NULL ENABLE, 
	"OPERATOR" VARCHAR2(64 CHAR) COLLATE "USING_NLS_COMP", 
	"REMARK" VARCHAR2(256 CHAR) COLLATE "USING_NLS_COMP", 
	"CREATE_TMS" TIMESTAMP (6) NOT NULL ENABLE, 
	"SIGN_SYNC_STATUS" VARCHAR2(32 CHAR) COLLATE "USING_NLS_COMP", 
	"SIGN_SYNC_RETRY_COUNT" NUMBER(22,0) DEFAULT 0, 
	"SIGN_SYNC_TIME" TIMESTAMP (6), 
	"SIGN_SYNC_RESULT" VARCHAR2(1024 CHAR) COLLATE "USING_NLS_COMP", 
	 CONSTRAINT "PK_USER_PHONE_CHANGE_LOG" PRIMARY KEY ("ID")
  USING INDEX PCTFREE 10 INITRANS 2 MAXTRANS 255 COMPUTE STATISTICS 
  STORAGE(INITIAL 65536 NEXT 1048576 MINEXTENTS 1 MAXEXTENTS 2147483645
  PCTINCREASE 0 FREELISTS 1 FREELIST GROUPS 1
  BUFFER_POOL DEFAULT FLASH_CACHE DEFAULT CELL_FLASH_CACHE DEFAULT)
  TABLESPACE "USERS"  ENABLE
   )  DEFAULT COLLATION "USING_NLS_COMP" SEGMENT CREATION IMMEDIATE 
  PCTFREE 10 PCTUSED 40 INITRANS 1 MAXTRANS 255 
 NOCOMPRESS LOGGING
  STORAGE(INITIAL 65536 NEXT 1048576 MINEXTENTS 1 MAXEXTENTS 2147483645
  PCTINCREASE 0 FREELISTS 1 FREELIST GROUPS 1
  BUFFER_POOL DEFAULT FLASH_CACHE DEFAULT CELL_FLASH_CACHE DEFAULT)
  TABLESPACE "USERS" ;

COMMENT ON COLUMN "QDITP"."USER_PHONE_CHANGE_LOG"."ID" IS '主键';
   COMMENT ON COLUMN "QDITP"."USER_PHONE_CHANGE_LOG"."THIRD_USER_ID" IS '第三方用户标识';
   COMMENT ON COLUMN "QDITP"."USER_PHONE_CHANGE_LOG"."USER_TYPE" IS '用户类型：ITP-地铁APP用户，ALIPAY-支付宝用户';
   COMMENT ON COLUMN "QDITP"."USER_PHONE_CHANGE_LOG"."OLD_MSISDN" IS '旧手机号';
   COMMENT ON COLUMN "QDITP"."USER_PHONE_CHANGE_LOG"."NEW_MSISDN" IS '新手机号';
   COMMENT ON COLUMN "QDITP"."USER_PHONE_CHANGE_LOG"."OPER_TYPE" IS '操作类型：CHANGE_PHONE-更换手机号';
   COMMENT ON COLUMN "QDITP"."USER_PHONE_CHANGE_LOG"."OPER_TIME" IS '操作时间';
   COMMENT ON COLUMN "QDITP"."USER_PHONE_CHANGE_LOG"."OPERATOR" IS '操作人/系统';
   COMMENT ON COLUMN "QDITP"."USER_PHONE_CHANGE_LOG"."REMARK" IS '备注';
   COMMENT ON COLUMN "QDITP"."USER_PHONE_CHANGE_LOG"."CREATE_TMS" IS '创建时间';
   COMMENT ON COLUMN "QDITP"."USER_PHONE_CHANGE_LOG"."SIGN_SYNC_STATUS" IS '向支付域同步显示账号的投递状态：PENDING-待投递，SUCCESS-已送达，FAILED-投递失败待重试；NULL 表示本行早于改造，NEVER 被补偿扫描捞取';
   COMMENT ON COLUMN "QDITP"."USER_PHONE_CHANGE_LOG"."SIGN_SYNC_RETRY_COUNT" IS '投递重试次数，达配置上限后不再扫描、转异常工单人工处理';
   COMMENT ON COLUMN "QDITP"."USER_PHONE_CHANGE_LOG"."SIGN_SYNC_TIME" IS '最近一次投递时间，配合 staleMinutes 判定 PENDING 滞留';
   COMMENT ON COLUMN "QDITP"."USER_PHONE_CHANGE_LOG"."SIGN_SYNC_RESULT" IS '最近一次投递的返回码与消息，超长由调用方截断';
   COMMENT ON TABLE "QDITP"."USER_PHONE_CHANGE_LOG"  IS '用户手机号更换历史记录表';


-- QDITP.LOGIC_CARD_POOL_CARD definition

CREATE TABLE "QDITP"."LOGIC_CARD_POOL_CARD" 
   (	"ID" NUMBER(22,0) GENERATED BY DEFAULT AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE, 
	"CARD_NO" VARCHAR2(64 CHAR) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"BATCH_NO" NUMBER(6,0) NOT NULL ENABLE, 
	"CARD_TYPE" VARCHAR2(4 CHAR) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"STATUS" VARCHAR2(16 CHAR) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"RESERVATION_ID" VARCHAR2(36 CHAR) COLLATE "USING_NLS_COMP", 
	"BUSINESS_TYPE" VARCHAR2(32 CHAR) COLLATE "USING_NLS_COMP", 
	"BUSINESS_ID" VARCHAR2(128 CHAR) COLLATE "USING_NLS_COMP", 
	"OWNER_ID" VARCHAR2(128 CHAR) COLLATE "USING_NLS_COMP", 
	"RESERVED_TIME" TIMESTAMP (6), 
	"EXPIRE_TIME" TIMESTAMP (6), 
	"CONFIRM_TIME" TIMESTAMP (6), 
	"CREATE_TIME" TIMESTAMP (6) DEFAULT SYSTIMESTAMP NOT NULL ENABLE, 
	"UPDATE_TIME" TIMESTAMP (6) DEFAULT SYSTIMESTAMP NOT NULL ENABLE, 
	 CONSTRAINT "PK_LOGIC_CARD_POOL_CARD" PRIMARY KEY ("ID")
  USING INDEX PCTFREE 10 INITRANS 2 MAXTRANS 255 COMPUTE STATISTICS 
  STORAGE(INITIAL 65536 NEXT 1048576 MINEXTENTS 1 MAXEXTENTS 2147483645
  PCTINCREASE 0 FREELISTS 1 FREELIST GROUPS 1
  BUFFER_POOL DEFAULT FLASH_CACHE DEFAULT CELL_FLASH_CACHE DEFAULT)
  TABLESPACE "USERS"  ENABLE, 
	 CONSTRAINT "UK_LOGIC_CARD_POOL_CARD_NO" UNIQUE ("CARD_NO")
  USING INDEX PCTFREE 10 INITRANS 2 MAXTRANS 255 COMPUTE STATISTICS 
  STORAGE(INITIAL 65536 NEXT 1048576 MINEXTENTS 1 MAXEXTENTS 2147483645
  PCTINCREASE 0 FREELISTS 1 FREELIST GROUPS 1
  BUFFER_POOL DEFAULT FLASH_CACHE DEFAULT CELL_FLASH_CACHE DEFAULT)
  TABLESPACE "USERS"  ENABLE, 
	 CONSTRAINT "UK_LOGIC_CARD_POOL_RESERVATION" UNIQUE ("RESERVATION_ID")
  USING INDEX PCTFREE 10 INITRANS 2 MAXTRANS 255 COMPUTE STATISTICS 
  STORAGE(INITIAL 65536 NEXT 1048576 MINEXTENTS 1 MAXEXTENTS 2147483645
  PCTINCREASE 0 FREELISTS 1 FREELIST GROUPS 1
  BUFFER_POOL DEFAULT FLASH_CACHE DEFAULT CELL_FLASH_CACHE DEFAULT)
  TABLESPACE "USERS"  ENABLE, 
	 CONSTRAINT "UK_LOGIC_CARD_POOL_BUSINESS" UNIQUE ("BUSINESS_TYPE", "BUSINESS_ID")
  USING INDEX PCTFREE 10 INITRANS 2 MAXTRANS 255 COMPUTE STATISTICS 
