  PCTINCREASE 0 FREELISTS 1 FREELIST GROUPS 1
  BUFFER_POOL DEFAULT FLASH_CACHE DEFAULT CELL_FLASH_CACHE DEFAULT)
  TABLESPACE "USERS"  ENABLE, 
	 CONSTRAINT "FK_LOGIC_CARD_POOL_CARD_BATCH" FOREIGN KEY ("BATCH_NO")
	  REFERENCES "QDITP"."LOGIC_CARD_POOL_BATCH" ("BATCH_NO") ENABLE
   )  DEFAULT COLLATION "USING_NLS_COMP" SEGMENT CREATION IMMEDIATE 
  PCTFREE 10 PCTUSED 40 INITRANS 1 MAXTRANS 255 
 NOCOMPRESS LOGGING
  STORAGE(INITIAL 65536 NEXT 1048576 MINEXTENTS 1 MAXEXTENTS 2147483645
  PCTINCREASE 0 FREELISTS 1 FREELIST GROUPS 1
  BUFFER_POOL DEFAULT FLASH_CACHE DEFAULT CELL_FLASH_CACHE DEFAULT)
  TABLESPACE "USERS" ;

COMMENT ON TABLE "QDITP"."LOGIC_CARD_POOL_CARD"  IS '逻辑卡号池明细';


-- QDITP.QRTZ_TRIGGERS definition

CREATE TABLE "QDITP"."QRTZ_TRIGGERS" 
   (	"SCHED_NAME" VARCHAR2(120 CHAR) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"TRIGGER_NAME" VARCHAR2(200 CHAR) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"TRIGGER_GROUP" VARCHAR2(200 CHAR) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"JOB_NAME" VARCHAR2(200 CHAR) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"JOB_GROUP" VARCHAR2(200 CHAR) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"DESCRIPTION" VARCHAR2(250 CHAR) COLLATE "USING_NLS_COMP", 
	"NEXT_FIRE_TIME" NUMBER(13,0), 
	"PREV_FIRE_TIME" NUMBER(13,0), 
	"PRIORITY" NUMBER(10,0), 
	"TRIGGER_STATE" VARCHAR2(16 CHAR) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"TRIGGER_TYPE" VARCHAR2(8 CHAR) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"START_TIME" NUMBER(13,0) NOT NULL ENABLE, 
	"END_TIME" NUMBER(13,0), 
	"CALENDAR_NAME" VARCHAR2(200 CHAR) COLLATE "USING_NLS_COMP", 
	"MISFIRE_INSTR" NUMBER(5,0), 
	"JOB_DATA" BLOB, 
	 CONSTRAINT "PK_QRTZ_TRIGGERS" PRIMARY KEY ("SCHED_NAME", "TRIGGER_NAME", "TRIGGER_GROUP")
  USING INDEX PCTFREE 10 INITRANS 2 MAXTRANS 255 COMPUTE STATISTICS 
  TABLESPACE "USERS"  ENABLE, 
	 CONSTRAINT "FK_QRTZ_TRIGGERS_JOB" FOREIGN KEY ("SCHED_NAME", "JOB_NAME", "JOB_GROUP")
