-- QDITP.TBL_RISK_RULE definition

CREATE TABLE "QDITP"."TBL_RISK_RULE" 
   (	"RULE_ID" VARCHAR2(16 CHAR) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"GROUP_ID" NUMBER(10,0), 
	"RULE_NAME" VARCHAR2(100 CHAR) COLLATE "USING_NLS_COMP" NOT NULL ENABLE, 
	"RISK_LEVEL" NUMBER(1,0) NOT NULL ENABLE, 
	"RISK_LIMIT_VALUE" NUMBER(12,2) NOT NULL ENABLE, 
	"MANAGER_CODE" VARCHAR2(64 CHAR) COLLATE "USING_NLS_COMP", 
	"REMARK" VARCHAR2(500 CHAR) COLLATE "USING_NLS_COMP", 
	"CREATE_TIME" DATE DEFAULT SYSDATE NOT NULL ENABLE, 
	"UPDATE_TIME" DATE DEFAULT SYSDATE NOT NULL ENABLE, 
	 CONSTRAINT "CK_RISK_RULE_LEVEL" CHECK (RISK_LEVEL BETWEEN 1 AND 5) ENABLE, 
	 CONSTRAINT "CK_RISK_RULE_LIMIT" CHECK (RISK_LIMIT_VALUE >= 0) ENABLE, 
	 CONSTRAINT "PK_TBL_RISK_RULE" PRIMARY KEY ("RULE_ID")
  USING INDEX PCTFREE 10 INITRANS 2 MAXTRANS 255 COMPUTE STATISTICS 
  STORAGE(INITIAL 65536 NEXT 1048576 MINEXTENTS 1 MAXEXTENTS 2147483645
  PCTINCREASE 0 FREELISTS 1 FREELIST GROUPS 1
  BUFFER_POOL DEFAULT FLASH_CACHE DEFAULT CELL_FLASH_CACHE DEFAULT)
  TABLESPACE "USERS"  ENABLE, 
	 CONSTRAINT "FK_RISK_RULE_GROUP" FOREIGN KEY ("GROUP_ID")
	  REFERENCES "QDITP"."TBL_RISK_GROUP" ("GROUP_ID") ENABLE
   )  DEFAULT COLLATION "USING_NLS_COMP" SEGMENT CREATION IMMEDIATE 
  PCTFREE 10 PCTUSED 40 INITRANS 1 MAXTRANS 255 
 NOCOMPRESS LOGGING
  STORAGE(INITIAL 65536 NEXT 1048576 MINEXTENTS 1 MAXEXTENTS 2147483645
  PCTINCREASE 0 FREELISTS 1 FREELIST GROUPS 1
  BUFFER_POOL DEFAULT FLASH_CACHE DEFAULT CELL_FLASH_CACHE DEFAULT)
  TABLESPACE "USERS" ;

COMMENT ON COLUMN "QDITP"."TBL_RISK_RULE"."RULE_ID" IS '风险规则编号';
   COMMENT ON COLUMN "QDITP"."TBL_RISK_RULE"."GROUP_ID" IS '所属风险组';
   COMMENT ON COLUMN "QDITP"."TBL_RISK_RULE"."RULE_NAME" IS '风险规则名称';
   COMMENT ON COLUMN "QDITP"."TBL_RISK_RULE"."RISK_LEVEL" IS '风险等级，1至5级';
   COMMENT ON COLUMN "QDITP"."TBL_RISK_RULE"."RISK_LIMIT_VALUE" IS '风险规则最大值或触发阈值';
   COMMENT ON COLUMN "QDITP"."TBL_RISK_RULE"."MANAGER_CODE" IS '管理编码';
   COMMENT ON COLUMN "QDITP"."TBL_RISK_RULE"."REMARK" IS '备注';
   COMMENT ON COLUMN "QDITP"."TBL_RISK_RULE"."CREATE_TIME" IS '创建时间';
